insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('apartment-lease-renewal-or-move-decision-sheet', 'Apartment Lease Renewal or Move Decision Sheet', 'worksheet'::resource_kind, 'A decision sheet for a client whose lease renewal notice has sat on the counter for two weeks while the deadline creeps closer.', 'Use it to lay out staying and moving side by side, name what the dread is really about, and pick a date to decide by.', array['Adults']::text[], '30 minutes', 'A lease renewal is a decision with a clock on it, and the client who hates both options tends to let the clock decide. The sheet asks for the facts of each path (rent, commute, what breaks, what they would miss), the feeling that comes up with each, which worry is about the apartment and which is about change itself, who they could ask one practical question, and the date by which they will choose. Keep the two columns honest; a client sometimes pads one side to justify the choice they already made. Watch for the client who wants you to decide; hand it back with a question.', '[{"id": "f0", "type": "textarea", "label": "What staying would cost and give me, in plain facts:"}, {"id": "f1", "type": "textarea", "label": "What moving would cost and give me, in plain facts:"}, {"id": "f2", "type": "textarea", "label": "The feeling that comes up with each option, and which one is about change itself:"}, {"id": "f3", "type": "textarea", "label": "One practical question I can ask someone this week (landlord, friend, a listing):"}, {"id": "f4", "type": "textarea", "label": "The date I will decide by, and what I will do if I still cannot:"}, {"id": "f5", "type": "textarea", "label": "What I will tell myself the day after I decide, whichever way it goes:"}]'::jsonb, array['decisions', 'planning', 'stress']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('three-weeks-of-unopened-mail-sorting-pacing-sheet', 'Three Weeks of Unopened Mail Sorting Pacing Sheet', 'worksheet'::resource_kind, 'A pacing sheet for the client whose mail has piled up unopened for weeks and now feels too frightening to touch.', 'Use it to open the pile in short timed rounds with a sorting rule, so the dread shrinks faster than the stack.', array['Adults']::text[], 'Three rounds of fifteen minutes across a week', 'An unopened pile grows a story about what is inside it, and the story is usually worse than the envelopes. The sheet sets three fifteen-minute rounds, each with four piles (act this week, file, recycle, ask someone), a prediction of what the worst envelope will say before opening, and what it actually said. The client stops at the timer even if they are on a roll; the point is that opening mail becomes ordinary again. Watch for the client who opens everything in one anxious burst and then avoids the next pile for a month; the pacing is the skill.', '[{"id": "f0", "type": "textarea", "label": "What I predict the worst envelope in the pile will say:"}, {"id": "f1", "type": "textarea", "label": "Round one: how many I opened, and what the worst one actually said:"}, {"id": "f2", "type": "textarea", "label": "Round two: what went into each pile (act, file, recycle, ask):"}, {"id": "f3", "type": "textarea", "label": "Round three: what is left, and who I can ask about the one I do not understand:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the dread from round one to round three:"}, {"id": "f5", "type": "textarea", "label": "My rule for mail from now on (where it lands, and which day I open it):"}]'::jsonb, array['avoidance', 'pacing', 'routines']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('side-work-versus-rest-weekend-hours-ledger-sheet', 'Side Work Versus Rest Weekend Hours Ledger Sheet', 'worksheet'::resource_kind, 'A ledger for the client who fills every weekend hour with a second job or side project and wonders why Monday feels like a wall.', 'Use it to count the real hours going to paid work, unpaid work and rest, and decide what one weekend with a floor on rest would look like.', array['Adults']::text[], '20 minutes, then one weekend', 'The client who is always working rarely knows how many hours that is; the sheet asks them to log last weekend hour by hour and sort each one as paid work, chores, caretaking, scrolling or rest that actually restored them. Then they set a floor (a number of rest hours that is not negotiable) and a plan for one weekend that meets it. Keep money fears in the room; the client often needs the income and the question is the margin, not the whole job. Watch for the client who logs scrolling as rest; ask whether it left them refilled or just elsewhere.', '[{"id": "f0", "type": "textarea", "label": "Last weekend hour by hour, with each hour sorted (paid work, chores, caretaking, scrolling, rest):"}, {"id": "f1", "type": "textarea", "label": "How many hours of real rest I got, and how that number lands:"}, {"id": "f2", "type": "textarea", "label": "What I am afraid would happen if I rested more:"}, {"id": "f3", "type": "textarea", "label": "My rest floor for next weekend, in hours, and where they will go:"}, {"id": "f4", "type": "textarea", "label": "One thing I will say no to or move to make room for it:"}, {"id": "f5", "type": "textarea", "label": "How Monday felt after last weekend, and how I want it to feel after this one:"}]'::jsonb, array['work', 'energy', 'self-care']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('neighbor-who-never-returned-the-ladder-ask-back-script', 'Neighbor Who Never Returned the Ladder Ask Back Script', 'worksheet'::resource_kind, 'A script sheet for the client who lent something months ago and has been avoiding the neighbor rather than asking for it back.', 'Use it to write a short, friendly ask, rehearse it, and set a day to say it, so the loan stops being a reason to avoid the driveway.', array['Adults']::text[], '15 minutes', 'Asking for a borrowed item back feels to some clients like an accusation, so they lose the ladder and the neighbor both. The sheet names the item, the story the client has built about why they cannot ask, a two-sentence friendly version (I need the ladder this weekend, could I grab it tomorrow), the worst realistic reply, and how they would handle it. Rehearse the line aloud until it sounds like a neighbor talking, not a lawyer. Watch for the client who wants to add an apology to the ask; strip it out and notice how it feels.', '[{"id": "f0", "type": "textarea", "label": "What I lent, to whom, and how long ago:"}, {"id": "f1", "type": "textarea", "label": "The story I have told myself about why I cannot ask:"}, {"id": "f2", "type": "textarea", "label": "My two-sentence ask, with no apology in it:"}, {"id": "f3", "type": "textarea", "label": "The worst realistic reply, and what I would say back:"}, {"id": "f4", "type": "textarea", "label": "The day and the moment I will ask (at the mailbox, by text, at the door):"}, {"id": "f5", "type": "textarea", "label": "How I felt afterward, and what I would do differently next time I lend something:"}]'::jsonb, array['assertiveness', 'avoidance', 'boundaries']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('leaving-the-dog-with-a-sitter-worry-handoff-sheet', 'Leaving the Dog With a Sitter Worry Handoff Sheet', 'worksheet'::resource_kind, 'A handoff sheet for the client whose trip is spoiled before it starts by worry about the pet they are leaving behind.', 'Use it to put the care instructions on paper, agree a check-in rhythm, and decide what the worry is allowed to do while they are away.', array['Adults']::text[], '20 minutes before the trip', 'The client who dreads leaving a pet usually gives the sitter too little information and themselves too many check-ins. The sheet separates the two: the written instructions the sitter actually needs (food, meds, the vet, the one quirk), a check-in rhythm agreed in advance (one photo a day at dinner), what the client will do when the worry spikes between check-ins, and what the worry is really about when the dog is not in the room. Keep it practical and warm. Watch for the client who plans to text the sitter hourly; negotiate a rhythm the sitter would agree to.', '[{"id": "f0", "type": "textarea", "label": "What the sitter actually needs to know, in a list they could tape to the fridge:"}, {"id": "f1", "type": "textarea", "label": "The one quirk about my pet I want them to understand:"}, {"id": "f2", "type": "textarea", "label": "Our check-in rhythm (how often, what form), agreed with the sitter:"}, {"id": "f3", "type": "textarea", "label": "What I will do when the worry spikes between check-ins:"}, {"id": "f4", "type": "textarea", "label": "What the worry might be about besides the dog:"}, {"id": "f5", "type": "textarea", "label": "How I want to feel on the first evening away, and what makes that possible:"}]'::jsonb, array['worry', 'planning', 'pets']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('responsibility-pie-for-the-rained-out-group-trip-sheet', 'Responsibility Pie for the Rained-Out Group Trip Sheet', 'cbt'::resource_kind, 'A responsibility pie chart for the client who planned a group outing, watched the weather ruin it, and took the whole failure as theirs.', 'Use it to divide the blame among every real cause, so the client''s slice shrinks to the size of what they actually controlled.', array['Adults', 'Teens']::text[], '20 minutes', 'The planner of a ruined day carries it as if they had ordered the rain. The pie chart lists every factor that made the trip go badly (the forecast, the venue''s rules, the friend who canceled, the client''s own choices), gives each a slice, and leaves the client''s share for last. Most clients are startled by how little is left. Then ask what their slice teaches for next time, which is the only useful part. Watch for the client who gives the weather a sliver and themselves half; walk through the slices again aloud.', '[{"id": "f0", "type": "textarea", "label": "What went wrong on the day, in a few plain lines:"}, {"id": "f1", "type": "textarea", "label": "Every factor that contributed, including ones nobody could control:"}, {"id": "f2", "type": "textarea", "label": "The slice of the pie each factor gets, with mine drawn last:"}, {"id": "f3", "type": "textarea", "label": "How big my slice turned out, and how that compares with how it felt:"}, {"id": "f4", "type": "textarea", "label": "What my slice actually teaches me for the next plan:"}, {"id": "f5", "type": "textarea", "label": "What I want to say to the friends about the day, now that the pie is drawn:"}]'::jsonb, array['self-blame', 'responsibility', 'CBT']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('i-am-bad-with-people-positive-data-log-sheet', 'I Am Bad With People Positive Data Log Sheet', 'cbt'::resource_kind, 'A positive data log in which the client collects two weeks of small evidence that does not fit the belief that they are bad with people.', 'Use it to build a record the belief cannot explain away, one ordinary exchange at a time.', array['Adults', 'Teens']::text[], 'Two minutes daily for two weeks', 'A client who believes they are bad with people filters out every exchange that went fine. The log asks for one small piece of evidence a day (a neighbor who smiled back, a coworker who asked them a question, a text that got a reply), the belief''s attempt to dismiss it, and a one-line reply to that dismissal. Set the bar low: evidence is anything the belief would predict could not happen. Review the two weeks together and ask what a stranger reading the log would conclude. Watch for the client who stops logging after a bad day; the bad day goes in the other column, and the log continues.', '[{"id": "f0", "type": "textarea", "label": "The belief, in my own words, and how much I believe it today out of 10:"}, {"id": "f1", "type": "textarea", "label": "Today''s evidence that does not fit, however small:"}, {"id": "f2", "type": "textarea", "label": "How the belief tried to dismiss it:"}, {"id": "f3", "type": "textarea", "label": "My one-line reply to the dismissal:"}, {"id": "f4", "type": "textarea", "label": "After two weeks, what the whole list says about me:"}, {"id": "f5", "type": "textarea", "label": "How much I believe the old belief now, out of 10:"}]'::jsonb, array['core beliefs', 'evidence', 'social skills']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('ask-the-barista-to-remake-the-drink-experiment-sheet', 'Ask the Barista to Remake the Drink Experiment Sheet', 'cbt'::resource_kind, 'A behavioral experiment in which the client asks for a wrong coffee order to be remade and records what happens.', 'Use it to test the prediction that a small complaint causes anger or contempt, against what the counter actually does.', array['Adults', 'Teens']::text[], 'One visit, then ten minutes to record', 'The client who drinks the wrong order rather than speak up is running a prediction they have never tested. The sheet asks for it in detail (the barista will roll their eyes, the line will groan, I will blush and leave), a confidence rating, the words the client will use, and then what happened, said and seen. Rehearse the sentence in session; it should be one line and polite. Debrief the gap between prediction and outcome, and ask what the client would predict next time. Watch for the client who says the outcome was fine only because the barista was unusually nice.', '[{"id": "f0", "type": "textarea", "label": "My prediction of what happens when I ask, as specific as I can make it:"}, {"id": "f1", "type": "textarea", "label": "How sure I am, out of 10:"}, {"id": "f2", "type": "textarea", "label": "The exact words I will use:"}, {"id": "f3", "type": "textarea", "label": "What actually happened: what they said, what their face did, how long it took:"}, {"id": "f4", "type": "textarea", "label": "How I felt in the ten minutes after:"}, {"id": "f5", "type": "textarea", "label": "What I predict next time, and how sure I am now:"}]'::jsonb, array['behavioral experiment', 'assertiveness', 'predictions']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('perfect-host-versus-terrible-host-continuum-sheet', 'Perfect Host Versus Terrible Host Continuum Sheet', 'cbt'::resource_kind, 'A continuum sheet for the client who believes any flaw in a dinner they host puts them at the terrible end of hosting.', 'Use it to draw the line from worst to best host, place real people on it, and find where one cold dish actually lands.', array['Adults']::text[], '25 minutes', 'All-or-nothing hosting puts the client at zero the moment the gravy breaks. The continuum asks them to describe the worst host imaginable and the best, then place people they know, hosts from their past, and finally themselves on a bad night and a good one. The cold dish lands in the middle somewhere, among the hosts whose company they still enjoyed. Make the ends extreme so the middle has room. Watch for the client who defines the worst host as someone who serves one imperfect thing; push until the ends are genuinely far apart.', '[{"id": "f0", "type": "textarea", "label": "The worst host I can imagine, described in detail:"}, {"id": "f1", "type": "textarea", "label": "The best host I can imagine, described in detail:"}, {"id": "f2", "type": "textarea", "label": "Hosts I know, placed along the line between them:"}, {"id": "f3", "type": "textarea", "label": "Where I land on the night the dish went cold, and why there:"}, {"id": "f4", "type": "textarea", "label": "Where I land on a good night:"}, {"id": "f5", "type": "textarea", "label": "What this does to the rule that one flaw makes me a terrible host:"}]'::jsonb, array['cognitive restructuring', 'perfectionism', 'holidays']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('cost-benefit-of-rereading-old-messages-sheet', 'Cost-Benefit of Rereading Old Messages Sheet', 'cbt'::resource_kind, 'A cost-benefit sheet for the client who reopens old texts or emails to reread a hurtful or confusing exchange.', 'Use it to weigh what the rereading gives and takes, and decide what to do with the thread instead.', array['Adults', 'Teens']::text[], '20 minutes', 'Rereading feels like it will finally settle what the message meant, and never does. The sheet lists the short-term benefits honestly (a sense of checking, a moment of certainty), the costs (the hour lost, the mood after, the way the words get sharper every read), and the long-term version of each. Then the client chooses one alternative for the next urge (archive the thread, ask the person, write the question down for session). Do not argue the benefits away. Watch for the client who rereads during the session to show you; put the phone face down and recall it instead.', '[{"id": "f0", "type": "textarea", "label": "The thread I keep going back to, and how often this week:"}, {"id": "f1", "type": "textarea", "label": "What rereading gives me in the moment, honestly:"}, {"id": "f2", "type": "textarea", "label": "What it costs me in the hour after, and over the month:"}, {"id": "f3", "type": "textarea", "label": "What I am hoping to find that has not been there the last twenty times:"}, {"id": "f4", "type": "textarea", "label": "What I will do with the next urge instead (archive, ask, write it down):"}, {"id": "f5", "type": "textarea", "label": "How I will know the alternative worked:"}]'::jsonb, array['cost-benefit', 'rumination', 'CBT']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('thoughts-as-hold-music-on-a-long-call-page', 'Thoughts as Hold Music on a Long Call Page', 'act'::resource_kind, 'An ACT defusion page in which the client treats a looping thought like hold music they can hear without hanging up on their day.', 'Use it to give a client an image for staying on the line with what matters while the mind plays the same tune again.', array['Adults', 'Teens']::text[], '10 minutes, then as needed', 'Hold music is designed to be noticed and impossible to act on, which makes it a good image for the thought that repeats all afternoon. The client names the thought, writes the tune it plays (the same six bars), and notices what they are actually waiting on the line for, which is the valued thing they were doing when it started. The point is not to make the music stop but to keep holding the phone. Practice with a mildly annoying thought first. Watch for the client who turns the image into a contest with the thought; the music is allowed to play.', '[{"id": "f0", "type": "textarea", "label": "The thought that loops, written as the hold music it is:"}, {"id": "f1", "type": "textarea", "label": "How long I usually stay on the line with it before I hang up on my day:"}, {"id": "f2", "type": "textarea", "label": "What I was actually holding for (the thing I care about) when it started:"}, {"id": "f3", "type": "textarea", "label": "How I can keep doing that thing while the music plays:"}, {"id": "f4", "type": "textarea", "label": "What I noticed the first time I let it play without reacting:"}, {"id": "f5", "type": "textarea", "label": "Where I will try this next:"}]'::jsonb, array['defusion', 'metaphor', 'ACT']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('values-on-the-long-drive-home-alone-page', 'Values on the Long Drive Home Alone Page', 'act'::resource_kind, 'An ACT values page for the client who spends a long solo drive home replaying the visit and arrives having decided nothing.', 'Use it to turn the empty miles into a values check, so the client steps out of the car with one direction instead of a rerun.', array['Adults']::text[], 'One drive, then ten minutes', 'The drive home after a family visit or a hard weekend is a long stretch of unstructured mind, and it tends to fill with replays. The page gives the client three questions to carry in the car: what mattered to them this weekend, when they acted like it and when they did not, and what one thing the next week could hold that points the same way. They answer aloud or in their head and write it down at the first stop. Keep the questions on a card on the dash. Watch for the client who uses the questions to grade themselves; values are a direction, not a score.', '[{"id": "f0", "type": "textarea", "label": "What mattered most to me this weekend, in a word or two:"}, {"id": "f1", "type": "textarea", "label": "A moment I acted like it mattered:"}, {"id": "f2", "type": "textarea", "label": "A moment I did not, and what pulled me off course:"}, {"id": "f3", "type": "textarea", "label": "One thing next week can hold that points the same direction:"}, {"id": "f4", "type": "textarea", "label": "What the replay wanted me to conclude, and what the values questions concluded instead:"}, {"id": "f5", "type": "textarea", "label": "Where I will keep the three questions for the next long drive:"}]'::jsonb, array['values', 'committed action', 'family']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('willing-to-leave-the-last-word-unsaid-page', 'Willing to Leave the Last Word Unsaid Page', 'act'::resource_kind, 'An ACT willingness page for the client who cannot let an argument end until they have had the final word.', 'Use it to practice ending a disagreement with the retort still in the mouth, and to notice what the urge is protecting.', array['Adults', 'Teens']::text[], '15 minutes, then one argument', 'The last word promises closure and delivers another round. The page asks the client to notice the retort as it forms, rate the urge to say it, name what they would be protecting by saying it (being right, being seen, not losing), and then choose to carry the unsaid line out of the room on purpose. Afterward they write what happened to the urge in the next hour and how the relationship looked the next morning. Make clear this is a chosen experiment, not swallowing a real need. Watch for the client who leaves the room and texts the last word instead.', '[{"id": "f0", "type": "textarea", "label": "The last argument, and the last word I wanted to have:"}, {"id": "f1", "type": "textarea", "label": "What saying it would have protected, honestly:"}, {"id": "f2", "type": "textarea", "label": "How strong the urge was, out of 10, and where I felt it:"}, {"id": "f3", "type": "textarea", "label": "What I did with the line instead (carried it, wrote it, let it go):"}, {"id": "f4", "type": "textarea", "label": "What the urge did over the next hour:"}, {"id": "f5", "type": "textarea", "label": "How the relationship looked the next morning compared with the times I said it:"}]'::jsonb, array['willingness', 'conflict', 'ACT']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('scraping-the-windshield-present-moment-page', 'Scraping the Windshield Present Moment Page', 'act'::resource_kind, 'An ACT present-moment page that uses the cold morning job of scraping ice off the windshield as a few minutes of contact with the senses.', 'Use it to give a client a daily winter chore in which to practice attention, so the day starts in the body rather than the inbox.', array['Adults']::text[], 'Five minutes on cold mornings', 'Scraping a windshield is cold, loud, repetitive and impossible to skip, which makes it a good anchor. The page asks the client to notice the sound of the scraper, the cold on the fingers, the breath turning to vapor, the line where clear glass begins, and the thoughts about the day that try to climb in, each time returning to the next stroke. They record one sensation they had never noticed before. Then they drive. Keep the frame light; this is noticing, not a ritual. Watch for the client who turns it into one more thing to do right.', '[{"id": "f0", "type": "textarea", "label": "The sound of the scraper, described as if to someone who has never heard it:"}, {"id": "f1", "type": "textarea", "label": "Where the cold reached first:"}, {"id": "f2", "type": "textarea", "label": "The thought about the day that climbed in, and how I came back to the glass:"}, {"id": "f3", "type": "textarea", "label": "One thing I noticed this morning that I never had before:"}, {"id": "f4", "type": "textarea", "label": "How the first mile of the drive felt compared with usual:"}, {"id": "f5", "type": "textarea", "label": "Which other cold-morning job I could use the same way:"}]'::jsonb, array['mindfulness', 'present moment', 'routines']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('mind-as-a-ticket-scanner-that-rejects-every-pass-page', 'Mind as a Ticket Scanner That Rejects Every Pass Page', 'act'::resource_kind, 'An ACT defusion page that casts the mind as a turnstile scanner beeping red at every plan the client tries to carry through.', 'Use it to help a client hear the mind''s rejections as a machine''s beep rather than a verdict on the plan.', array['Adults', 'Teens']::text[], '10 minutes', 'Some minds reject every plan with the same tone: this will not work, you will fail, they will laugh. The page gives that voice a body, a ticket scanner at a gate that beeps red at every pass without reading it. The client lists three plans the scanner rejected, what the beep said, whether the beep ever reads the ticket, and what happened the times they walked through anyway. The exercise is not to argue with the scanner but to notice it is a scanner. Watch for the client who wants to fix the machine first; the gate can be walked through while it beeps.', '[{"id": "f0", "type": "textarea", "label": "Three plans my mind beeped red at this month:"}, {"id": "f1", "type": "textarea", "label": "The exact words the beep uses:"}, {"id": "f2", "type": "textarea", "label": "Whether the beep ever reads the ticket or just beeps:"}, {"id": "f3", "type": "textarea", "label": "A time I walked through anyway, and what happened on the other side:"}, {"id": "f4", "type": "textarea", "label": "The plan I will try to walk through this week while it beeps:"}, {"id": "f5", "type": "textarea", "label": "What I will say to myself as the beep goes off:"}]'::jsonb, array['defusion', 'metaphor', 'avoidance']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('dear-man-for-the-neighbors-barking-dog-card', 'DEAR MAN for the Neighbor''s Barking Dog Card', 'dbt'::resource_kind, 'A DEAR MAN card for the client whose neighbor''s dog barks for hours and who has been seething rather than knocking.', 'Use it to script a clear, respectful request for a specific change, and rehearse staying mindful if the neighbor gets defensive.', array['Adults']::text[], '20 minutes to script, one conversation', 'The barking dog request goes wrong in two directions: never made, or made at full volume after a bad night. The card walks the client through Describe (the hours, not the character), Express (how the noise lands), Assert (the specific ask, such as bringing the dog in after nine), Reinforce (what it gives the neighbor), then Mindful, Appear confident and Negotiate. Rehearse the neighbor''s likely defenses and the client''s broken-record return to the ask. Watch for the client whose Describe is a list of grievances; cut it to one sentence of fact.', '[{"id": "f0", "type": "textarea", "label": "Describe: the facts about the barking, without judgment, in one or two sentences:"}, {"id": "f1", "type": "textarea", "label": "Express: how it affects me, in one sentence:"}, {"id": "f2", "type": "textarea", "label": "Assert: the specific change I am asking for:"}, {"id": "f3", "type": "textarea", "label": "Reinforce: what the neighbor gets out of agreeing:"}, {"id": "f4", "type": "textarea", "label": "Mindful: the line I will return to if they go off topic or get defensive:"}, {"id": "f5", "type": "textarea", "label": "Negotiate: what I could accept that is not my first ask:"}]'::jsonb, array['DEAR MAN', 'interpersonal effectiveness', 'neighbors']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-leaving-the-group-chat-grid', 'Pros and Cons of Leaving the Group Chat Grid', 'dbt'::resource_kind, 'A DBT pros and cons grid for the client who wants to leave a draining group chat and fears what leaving would say.', 'Use it to weigh staying and leaving, now and later, before the client acts on the next irritating message.', array['Adults', 'Teens']::text[], '20 minutes', 'The grid has four cells: pros and cons of leaving, pros and cons of staying, each split into short-term and long-term. The client who fills it usually finds the short-term pros of leaving are relief and the long-term cons are a conversation they would have to have anyway. A third option often appears (mute, read weekly, say less) that neither side had considered. Fill the grid when calm, then revisit it the next time a message stings. Watch for the client who fills only the leaving side; both options get all four cells.', '[{"id": "f0", "type": "textarea", "label": "Pros of leaving the chat, short-term and long-term:"}, {"id": "f1", "type": "textarea", "label": "Cons of leaving, short-term and long-term:"}, {"id": "f2", "type": "textarea", "label": "Pros of staying, short-term and long-term:"}, {"id": "f3", "type": "textarea", "label": "Cons of staying, short-term and long-term:"}, {"id": "f4", "type": "textarea", "label": "A third option the grid made me notice:"}, {"id": "f5", "type": "textarea", "label": "What I will do the next time a message in it stings:"}]'::jsonb, array['pros and cons', 'decisions', 'boundaries']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('self-soothe-under-the-heavy-quilt-on-a-dark-afternoon-card', 'Self-Soothe Under the Heavy Quilt on a Dark Afternoon Card', 'dbt'::resource_kind, 'A DBT self-soothe card built around the weight and warmth of a heavy quilt for the early dark of winter afternoons.', 'Use it to give a client a ten-minute sensory reset that is already in the house when the four o''clock dark pulls the mood down.', array['Adults', 'Teens']::text[], 'Ten minutes', 'When the afternoon goes dark by four, some clients lose the rest of the day to it. The card sets a ten-minute self-soothe under a heavy quilt with the lamp on: the weight across the shoulders and legs, the warmth building, the texture under the fingers, one sound in the room, one smell nearby. Ten minutes and then one small next thing (a light on in the kitchen, a kettle). It is a reset, not a retreat, and the timer matters. Watch for the client who stays under the quilt until bedtime; the card ends with standing up.', '[{"id": "f0", "type": "textarea", "label": "Where the weight of the quilt landed first, and what it did to my shoulders:"}, {"id": "f1", "type": "textarea", "label": "The warmth building, described minute by minute:"}, {"id": "f2", "type": "textarea", "label": "One sound in the room, and one smell nearby:"}, {"id": "f3", "type": "textarea", "label": "What my mind did with ten quiet minutes:"}, {"id": "f4", "type": "textarea", "label": "The one small next thing I did when the timer went:"}, {"id": "f5", "type": "textarea", "label": "How the evening went compared with afternoons without the reset:"}]'::jsonb, array['self-soothing', 'distress tolerance', 'winter']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('check-the-facts-on-the-neighbor-who-did-not-wave-card', 'Check the Facts on the Neighbor Who Did Not Wave Card', 'dbt'::resource_kind, 'A DBT check the facts card for the client who read a neighbor''s missed wave as a snub and has been stewing since.', 'Use it to separate what was seen from what was assumed, and decide whether the hurt fits the facts.', array['Adults', 'Teens']::text[], '10 minutes', 'A missed wave is a small event that can run a whole evening. The card walks the client through the prompting event (they drove past, I waved, they did not), the interpretation (they are angry about something), the emotion and its intensity, the alternative explanations (sun in their eyes, a phone call, a bad day), and whether the emotion fits the facts as they are known. If it does not, the client picks a next step (wave again tomorrow, say hello). Keep it to one event. Watch for the client who checks the facts and then adds three older grievances as evidence.', '[{"id": "f0", "type": "textarea", "label": "What actually happened, in one sentence a camera would agree with:"}, {"id": "f1", "type": "textarea", "label": "What I assumed it meant:"}, {"id": "f2", "type": "textarea", "label": "The emotion and how strong it was, out of 10:"}, {"id": "f3", "type": "textarea", "label": "Three other explanations that fit the same facts:"}, {"id": "f4", "type": "textarea", "label": "Does the emotion fit the facts I actually have? What would make it fit?"}, {"id": "f5", "type": "textarea", "label": "What I will do the next time I see them:"}]'::jsonb, array['check the facts', 'emotion regulation', 'neighbors']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('build-mastery-by-fixing-the-wobbly-chair-card', 'Build Mastery by Fixing the Wobbly Chair Card', 'dbt'::resource_kind, 'A DBT build mastery card for the client who has stepped around a wobbly kitchen chair for months and could fix it in twenty minutes.', 'Use it to give a client one small competent act they can finish today and point to tomorrow.', array['Adults', 'Teens']::text[], '20 to 30 minutes', 'Mastery grows from finishing things that are slightly hard, and a wobbly chair is exactly that: a tightened bolt or a dab of glue, a task with a clear end and a chair that stops rocking. The card asks the client to pick the small broken thing (the chair, a drawer, a loose handle), look up how to fix it, do it, and sit on the result. Then they rate the sense of competence before and after and choose the next small fix. Avoid anything that needs a new tool or a trip; the point is finishing today. Watch for the client who picks the whole garage; one chair.', '[{"id": "f0", "type": "textarea", "label": "The small broken thing I have been stepping around:"}, {"id": "f1", "type": "textarea", "label": "How I will fix it, in three steps, and what I need that is already in the house:"}, {"id": "f2", "type": "textarea", "label": "How I felt about myself before, out of 10:"}, {"id": "f3", "type": "textarea", "label": "What happened when I did it, including anything that went wrong:"}, {"id": "f4", "type": "textarea", "label": "How I felt about myself after, out of 10:"}, {"id": "f5", "type": "textarea", "label": "The next small fix, and the day I will do it:"}]'::jsonb, array['build mastery', 'emotion regulation', 'habits']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('after-the-guests-leave-debrief-ritual-for-partners', 'After the Guests Leave Debrief Ritual for Partners', 'couples'::resource_kind, 'A couples debrief for the hour after guests go home, so the evening is reviewed together rather than relitigated at bedtime.', 'Use it to give partners a short, kind format for what went well, what stung, and what to change for next time.', array['Couples']::text[], '20 minutes after the door closes', 'The hour after guests leave is when one partner wants to collapse and the other wants to replay every moment, usually the moment the first partner got wrong. The ritual gives it a shape: each partner names one thing the other did that helped, one moment that stung and what they wished had happened, and one change for next time, in that order, with no interruptions. Then the dishes, or bed. The order matters; the appreciation goes first and is not skipped. Watch for the couple whose sting section runs long; cap it at one each and send the rest to a later session.', '[{"id": "f0", "type": "textarea", "label": "Partner A: one thing you did tonight that helped me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: one thing you did tonight that helped me:"}, {"id": "f2", "type": "textarea", "label": "Partner A: one moment that stung, and what I wished had happened instead:"}, {"id": "f3", "type": "textarea", "label": "Partner B: one moment that stung, and what I wished had happened instead:"}, {"id": "f4", "type": "textarea", "label": "Our one change for next time, agreed by both:"}, {"id": "f5", "type": "textarea", "label": "What we will do right after this debrief (dishes, bed, a show):"}]'::jsonb, array['couples', 'repair', 'hosting']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('working-from-home-interruptions-pact-for-partners', 'Working From Home Interruptions Pact for Partners', 'couples'::resource_kind, 'A couples pact for the partner who works from home and the partner who keeps popping in with a question.', 'Use it to agree on signals, hours and exceptions so the interruptions stop feeling like disrespect in either direction.', array['Couples']::text[], 'One session', 'The home office fight has two true sides: the working partner feels their job is treated as optional, and the other feels shut out of their own house. The pact asks each to describe a typical interruption from their seat, then agree on a signal for do not disturb (a door, a lamp, headphones), the hours it applies, what counts as an exception, and when the working partner is fully available. Both partners'' parts are written and read aloud. Watch for the pact that is all rules for the interrupter; the working partner commits to an end time too.', '[{"id": "f0", "type": "textarea", "label": "Working partner: what an interruption does to my work and my mood, in a typical case:"}, {"id": "f1", "type": "textarea", "label": "Other partner: what it is like to live beside a closed door all day:"}, {"id": "f2", "type": "textarea", "label": "Our do-not-disturb signal, and the hours it applies:"}, {"id": "f3", "type": "textarea", "label": "What counts as an exception worth interrupting for:"}, {"id": "f4", "type": "textarea", "label": "Working partner: the time I close the laptop and am fully here:"}, {"id": "f5", "type": "textarea", "label": "How we will check in on the pact after two weeks:"}]'::jsonb, array['couples', 'boundaries', 'work']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('two-cooks-in-one-kitchen-roles-pact-for-partners', 'Two Cooks in One Kitchen Roles Pact for Partners', 'couples'::resource_kind, 'A couples pact for partners who both want to run the kitchen and end up snapping over the stove.', 'Use it to divide the cooking into roles and zones before the next meal, so the kitchen is shared rather than contested.', array['Couples']::text[], '20 minutes before a shared cooking day', 'Two capable cooks in one kitchen is a recipe for correcting each other''s knife work. The pact asks each partner what they love doing in the kitchen, what they hate being corrected on, and what they would happily hand over. Then they divide the next shared meal into roles (who leads, who preps, who cleans as they go) and zones, and agree on one phrase for offering help that is not a correction. Rehearse the phrase. Watch for the partner who takes every role on paper and resents it at the stove; the division should leave both with something they enjoy.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I love doing in the kitchen, and what I hate being corrected on:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I love doing in the kitchen, and what I hate being corrected on:"}, {"id": "f2", "type": "textarea", "label": "Who leads the next shared meal, and who preps and cleans as we go:"}, {"id": "f3", "type": "textarea", "label": "Our zones, so we are not reaching across each other:"}, {"id": "f4", "type": "textarea", "label": "The one phrase we will use to offer help that is not a correction:"}, {"id": "f5", "type": "textarea", "label": "How the next meal went, and what we would change:"}]'::jsonb, array['couples', 'conflict', 'fairness']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('teasing-in-front-of-friends-agreement-for-partners', 'Teasing in Front of Friends Agreement for Partners', 'couples'::resource_kind, 'A couples agreement for the partner who teases in company and the partner who laughs along and hurts afterward.', 'Use it to name which jokes land and which do not, and agree on a signal and a repair for when one slips out.', array['Couples']::text[], 'One session', 'Teasing in front of friends is affection to one partner and a public jab to the other, and the hurt partner often says nothing until the car. The agreement asks the teased partner to list jokes that are fine and jokes that are not, the teasing partner to say what the teasing is for (connection, nervousness, habit), and both to agree on a private signal for stop and a repair for the ride home. Keep the list concrete. Watch for the teasing partner who hears the list as censorship; the fine column is theirs to keep.', '[{"id": "f0", "type": "textarea", "label": "Teased partner: jokes about me that are fine in company:"}, {"id": "f1", "type": "textarea", "label": "Teased partner: jokes that are not, and what each one costs me:"}, {"id": "f2", "type": "textarea", "label": "Teasing partner: what the teasing is doing for me when I do it:"}, {"id": "f3", "type": "textarea", "label": "Our private signal for stop, and what the teasing partner does when they see it:"}, {"id": "f4", "type": "textarea", "label": "Our repair on the ride home if one slips out:"}, {"id": "f5", "type": "textarea", "label": "Teasing partner: what I will do with the urge to joke when I notice it rising:"}]'::jsonb, array['couples', 'repair', 'respect']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('different-bedtime-routines-wind-down-pact-for-partners', 'Different Bedtime Routines Wind-Down Pact for Partners', 'couples'::resource_kind, 'A couples pact for the partner who needs quiet and dark by ten and the partner who reads, scrolls or talks in bed.', 'Use it to agree on light, sound and talk in the shared bed so neither partner lies awake resenting the other.', array['Couples']::text[], '20 minutes', 'One partner''s wind-down is the other''s wake-up: the lamp, the phone glow, the question asked at eleven. The pact asks each partner what they need in the last half hour before sleep and what the other''s routine does to theirs, then sets agreements on light (a reading light, not the lamp), sound, screens, and when talk ends. It also names a fair place for the night owl''s last hour that is not the bed. Both partners give something. Watch for the pact that reads like one partner''s rules; each gets a need met.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I need in the last half hour before sleep:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I need in the last half hour before sleep:"}, {"id": "f2", "type": "textarea", "label": "What the other''s routine does to mine, said kindly:"}, {"id": "f3", "type": "textarea", "label": "Our agreements on light, sound and screens in the bed:"}, {"id": "f4", "type": "textarea", "label": "When talk ends for the night, and where the last question goes if it cannot wait:"}, {"id": "f5", "type": "textarea", "label": "Where the later partner spends the last hour, and what makes that place comfortable:"}]'::jsonb, array['couples', 'sleep', 'routines']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('pie-tin-tambourine-shake-out-the-big-feeling-craft', 'Pie Tin Tambourine Shake Out the Big Feeling Craft', 'kids'::resource_kind, 'A craft in which a child turns two foil pie tins into a tambourine and learns to shake a big feeling out loud before talking about it.', 'Use it to give a young child a noisy, physical release that ends with a quiet question from the parent.', array['Children']::text[], '25 minutes to make, then two minutes as needed', 'Two foil pie tins, a handful of dried beans and tape make a tambourine in ten minutes; stickers and markers make it theirs. The rule the parent teaches: when a feeling is too big for words, shake it as loud as it is, then softer, then stop, and the parent asks one quiet question (what was that one about). The shaking gives the body something to do and the softening gives the feeling a way down. The parent makes their own and uses it first, so the child sees a grown-up shake out a frustration. Watch for the child who only shakes loud; practice the softening with them.', '[{"id": "f0", "type": "textarea", "label": "What I decorated my tambourine with:"}, {"id": "f1", "type": "textarea", "label": "A feeling that is too big for words, and what it sounds like on the tambourine:"}, {"id": "f2", "type": "textarea", "label": "How I make the shaking get softer:"}, {"id": "f3", "type": "textarea", "label": "The quiet question my grown-up asks when I stop:"}, {"id": "f4", "type": "textarea", "label": "A time my grown-up used their tambourine, and what they were feeling:"}, {"id": "f5", "type": "textarea", "label": "Where my tambourine lives so I can find it fast:"}]'::jsonb, array['children', 'craft', 'regulation']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('dandelion-puff-cotton-ball-slow-breath-play', 'Dandelion Puff Cotton Ball Slow Breath Play', 'kids'::resource_kind, 'A breathing play in which a child blows a cotton ball across the table as slowly as a dandelion puff, not as fast as a race.', 'Use it to teach a slow, long out-breath to a young child who tends to breathe hard and fast when upset.', array['Children']::text[], '10 minutes', 'Most breathing games for children end up as races, and a race speeds the breath up. This one does the opposite: the cotton ball is a dandelion puff, and the goal is to move it the whole way across the table with the slowest breath possible without it stopping. The parent goes first and loses on purpose by blowing too hard. Then the child tries, and the pair notice how the slow breath feels in the belly. The game is then available when the child is wound up: the puff is on the table, can you move it slowly. Watch for the child who hyperventilates trying; two breaths, then rest.', '[{"id": "f0", "type": "textarea", "label": "How far my puff went on one slow breath:"}, {"id": "f1", "type": "textarea", "label": "What a too-fast breath did to the puff:"}, {"id": "f2", "type": "textarea", "label": "Where I felt the slow breath in my body:"}, {"id": "f3", "type": "textarea", "label": "How my grown-up''s slow breath went:"}, {"id": "f4", "type": "textarea", "label": "A time I could use the slow puff breath:"}, {"id": "f5", "type": "textarea", "label": "Where the cotton ball lives so it is ready:"}]'::jsonb, array['children', 'breathing', 'play']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('lunch-bag-puppet-who-says-what-i-need-play', 'Lunch Bag Puppet Who Says What I Need Play', 'kids'::resource_kind, 'A puppet play in which a child makes a paper lunch bag puppet whose job is to say the hard thing the child cannot say directly.', 'Use it to give a child a safe mouth for asking, refusing and telling, with the parent as the puppet''s audience.', array['Children']::text[], '30 minutes to make, 10 minutes to play', 'A paper lunch bag, markers and glued-on paper ears become a puppet whose one job is to say what the child needs: I want a turn, I do not like that, I need help, I am scared. The parent asks the puppet, not the child, and the puppet answers, which takes the heat off. Then the parent practices receiving the hard sentence well (thank you for telling me) so the child learns that asking works. Keep the puppet''s sentences short and the parent''s response warm. Watch for the parent who corrects the puppet''s grammar or tone; the puppet is practicing, and practice is messy.', '[{"id": "f0", "type": "textarea", "label": "My puppet''s name, and what it looks like:"}, {"id": "f1", "type": "textarea", "label": "Something my puppet is good at saying that I find hard:"}, {"id": "f2", "type": "textarea", "label": "What my puppet said to my grown-up today:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up said back:"}, {"id": "f4", "type": "textarea", "label": "A time this week my puppet could help me say something:"}, {"id": "f5", "type": "textarea", "label": "How it felt when my grown-up listened to the puppet:"}]'::jsonb, array['children', 'assertiveness', 'play']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('button-jar-sort-and-settle-quiet-hands-play', 'Button Jar Sort and Settle Quiet Hands Play', 'kids'::resource_kind, 'A quiet play in which a child sorts a jar of mixed buttons by color or size while the body settles after a busy day.', 'Use it to give a child a slow, repetitive hands-on task for the gap between activity and rest, with the parent sorting beside them.', array['Children']::text[], '10 to 15 minutes', 'Sorting is soothing in a way children feel before they can say it: one button, one decision, one small sound in the dish. The play is a jar of mixed buttons and a muffin tin or egg carton; the child picks the rule (color, size, number of holes) and sorts in silence or with soft talk. The parent sorts their own handful beside them rather than directing. After, the child notices how their body feels compared with before and decides where the jar lives. Watch for the parent who turns it into a counting lesson; this one is for settling, not learning.', '[{"id": "f0", "type": "textarea", "label": "The rule I used to sort today (color, size, holes, something else):"}, {"id": "f1", "type": "textarea", "label": "How my body felt before I started:"}, {"id": "f2", "type": "textarea", "label": "How it felt when the jar was empty:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up sorted, and whether we talked or stayed quiet:"}, {"id": "f4", "type": "textarea", "label": "A time of day the button jar would help me:"}, {"id": "f5", "type": "textarea", "label": "Where the jar lives so I can reach it:"}]'::jsonb, array['children', 'regulation', 'play']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('clothespin-family-who-helps-me-with-what-play', 'Clothespin Family Who Helps Me With What Play', 'kids'::resource_kind, 'A play in which a child decorates clothespin people for the grown-ups in their life and matches each to the kind of help they are good for.', 'Use it to help a child see they have several helpers and to know who to go to for which kind of trouble.', array['Children']::text[], '30 minutes', 'Wooden clothespins, markers and scraps of fabric make a small set of people: a parent, a grandparent, a teacher, a coach, a neighbor. The child decorates each, then the parent lays out cards for kinds of trouble (scared, hurt, confused about homework, someone being unkind) and the child stands a clothespin person on each, sometimes several. The talk that follows is who the child would actually go to, and the parent fills gaps gently. Watch for the child who puts one person on every card; name it warmly and add a second helper to two of them.', '[{"id": "f0", "type": "textarea", "label": "The people I made, and what each one looks like:"}, {"id": "f1", "type": "textarea", "label": "Who I would go to if I were scared:"}, {"id": "f2", "type": "textarea", "label": "Who I would go to if I were hurt or sick:"}, {"id": "f3", "type": "textarea", "label": "Who I would go to if someone was being unkind to me:"}, {"id": "f4", "type": "textarea", "label": "Who I would go to for help with something hard at school:"}, {"id": "f5", "type": "textarea", "label": "Where my clothespin people will stand so I remember them:"}]'::jsonb, array['children', 'support', 'craft']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('two-truths-and-a-hope-circle-game', 'Two Truths and a Hope Circle Game', 'game'::resource_kind, 'A circle game in which each person shares two true things about their week and one hope, and the group guesses which is the hope.', 'Use it to open a group with real disclosure and a forward look, without putting anyone''s hardest thing on the table.', array['Groups', 'Teens']::text[], '15 minutes', 'Rules: each member says three short statements in any order, two true things from their week and one thing they hope happens next week, told as if it already had. The group votes on which is the hope; the speaker reveals it and says one step they could take toward it. Everyone goes once; passing on the step is allowed, passing on the turn is not. Debrief: what made a hope hard to spot, and what it was like to say a hope aloud as if it were true. Watch for the member whose hope is enormous; ask for the smallest version.', '[{"id": "f0", "type": "textarea", "label": "My two truths and my hope, in the order I said them:"}, {"id": "f1", "type": "textarea", "label": "Whether the group guessed, and what gave it away:"}, {"id": "f2", "type": "textarea", "label": "The one step I could take toward my hope:"}, {"id": "f3", "type": "textarea", "label": "A hope from someone else I would like to see happen:"}, {"id": "f4", "type": "textarea", "label": "What it was like to say my hope as if it were already true:"}, {"id": "f5", "type": "textarea", "label": "The hope I will check on next week:"}]'::jsonb, array['group', 'game', 'hope']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('mixed-message-draw-and-describe-chain-game', 'Mixed Message Draw and Describe Chain Game', 'game'::resource_kind, 'A chain game in which a message passes down a line, alternating between a drawing and a description, then meets the original.', 'Use it to show a group how a message changes hands, and to open a talk about asking rather than assuming.', array['Groups', 'Teens']::text[], '20 minutes', 'Rules: the first player writes a short sentence about an everyday moment (my neighbor waved from across the street). The next draws it with no words, the next writes what the drawing shows, the next draws that, and so on down the line. The last version is read beside the first. Two rounds with different starters. Debrief: where the meaning shifted, who could have asked a question and did not, and where in the members'' own week a message traveled this far. Watch for the member embarrassed by their drawing; stick figures are the rule, not the exception.', '[{"id": "f0", "type": "textarea", "label": "The sentence that started my chain:"}, {"id": "f1", "type": "textarea", "label": "What the last version said:"}, {"id": "f2", "type": "textarea", "label": "Where I think the meaning shifted:"}, {"id": "f3", "type": "textarea", "label": "A moment this week when a message about me probably changed hands like this:"}, {"id": "f4", "type": "textarea", "label": "What I could have asked instead of assuming:"}, {"id": "f5", "type": "textarea", "label": "A message I will check at the source this week:"}]'::jsonb, array['group', 'game', 'communication']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('kind-questions-only-hot-seat-game', 'Kind Questions Only Hot Seat Game', 'game'::resource_kind, 'A hot seat game in which one player takes questions for two minutes, and only kind, curious questions are allowed.', 'Use it to practice being the center of attention in a group with the rules tilted toward warmth.', array['Groups', 'Teens']::text[], '20 minutes', 'Rules: one player sits in the hot seat for two minutes while the group asks questions. Every question must be kind and curious (what are you proud of this month, what do you do on a slow Sunday); the facilitator vetoes anything with a barb. The seated player may pass twice. Everyone sits once. Debrief: what it was like to be asked about rather than talked about, which question surprised you, and how the body felt in the first thirty seconds versus the last. Watch for the member who deflects every question with a joke; the second pass is allowed, the third gets a gentle nudge.', '[{"id": "f0", "type": "textarea", "label": "The question I liked being asked most:"}, {"id": "f1", "type": "textarea", "label": "The question that surprised me:"}, {"id": "f2", "type": "textarea", "label": "How my body felt in the first thirty seconds in the seat:"}, {"id": "f3", "type": "textarea", "label": "How it felt by the end of two minutes:"}, {"id": "f4", "type": "textarea", "label": "A kind question I asked someone else:"}, {"id": "f5", "type": "textarea", "label": "Someone I could ask one of these questions outside the group:"}]'::jsonb, array['group', 'game', 'social skills']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('paper-airplane-message-to-my-future-self-game', 'Paper Airplane Message to My Future Self Game', 'game'::resource_kind, 'A game in which each member writes a line to themselves one month ahead on a paper airplane and flies it to the group''s landing zone.', 'Use it to end a group with a light, physical act of forward-looking kindness that the facilitator returns a month later.', array['Groups', 'Teens']::text[], '15 minutes', 'Rules: each member writes one sentence to their future self (a reminder, a wish, a dare), folds the page into an airplane, and on the count of three everyone flies them toward a taped landing zone. Planes outside the zone get one more throw. The facilitator collects them, keeps them sealed, and hands them back in a month. Debrief now: what you chose to say and why; debrief in a month: whether the message landed. Watch for the member who writes something harsh to themselves; ask them to write it as they would to a friend.', '[{"id": "f0", "type": "textarea", "label": "The sentence I wrote to myself a month from now:"}, {"id": "f1", "type": "textarea", "label": "Why that sentence, today:"}, {"id": "f2", "type": "textarea", "label": "Whether my plane made the zone, and how many throws it took:"}, {"id": "f3", "type": "textarea", "label": "A sentence I would write to someone else in the room:"}, {"id": "f4", "type": "textarea", "label": "What I expect to feel when I get the plane back:"}, {"id": "f5", "type": "textarea", "label": "A month later: what the message meant when it landed:"}]'::jsonb, array['group', 'game', 'hope']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('silent-ball-toss-catch-the-eye-first-game', 'Silent Ball Toss Catch the Eye First Game', 'game'::resource_kind, 'A quiet group game in which a soft ball is tossed only to someone who has made eye contact first, with no talking allowed.', 'Use it to settle a loud group and practice reading faces, waiting and being chosen without words.', array['Groups', 'Teens']::text[], '10 minutes', 'Rules: the group stands in a loose circle in silence. A player may only throw the soft ball to someone whose eye they have caught and who has nodded. A throw without the look, a drop, or any talking sends the thrower to sit for one round. Play three rounds; the last round, each player must throw to someone they have not yet thrown to. Debrief aloud: what it was like to wait to be looked at, what you noticed in faces, and whether the silence was calm or tense. Watch for the player nobody chooses; the last-round rule is there for them.', '[{"id": "f0", "type": "textarea", "label": "How long I waited before someone caught my eye:"}, {"id": "f1", "type": "textarea", "label": "What I noticed in people''s faces during the silence:"}, {"id": "f2", "type": "textarea", "label": "Whether the quiet felt calm or tense to me, and when it changed:"}, {"id": "f3", "type": "textarea", "label": "Who I threw to in the last round that I had not before:"}, {"id": "f4", "type": "textarea", "label": "A place in my week where I could catch someone''s eye before speaking:"}, {"id": "f5", "type": "textarea", "label": "What I would change about the rules:"}]'::jsonb, array['group', 'game', 'mindfulness']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('hard-date-on-the-calendar-week-before-steadiness-sheet', 'Hard Date on the Calendar Week Before Steadiness Sheet', 'worksheet'::resource_kind, 'A steadiness sheet for the seven days before a date the client''s body remembers, with anchors, people and permissions set in advance.', 'Use it to make the week before a hard date a plan rather than a countdown the client faces alone.', array['Adults', 'Teens']::text[], '20 minutes, a week ahead', 'The days before a hard date often go worse than the date itself, because the body starts bracing early. The sheet asks what the client usually notices in the week before (sleep, startle, irritability), one steadying anchor for each day, who knows the date is coming and what they have been asked to do, what the client is allowed to skip that week, and a plan for the day itself that is theirs to choose. Stay with the present week; the past is not the homework. Watch for the client who plans to power through as if the date were any other; permission to ease off is part of the plan.', '[{"id": "f0", "type": "textarea", "label": "What my body usually does in the week before this date:"}, {"id": "f1", "type": "textarea", "label": "One steadying thing for each of the seven days, however small:"}, {"id": "f2", "type": "textarea", "label": "Who knows the date is coming, and what I have asked them to do:"}, {"id": "f3", "type": "textarea", "label": "What I am allowed to skip or shorten this week:"}, {"id": "f4", "type": "textarea", "label": "What I want the day itself to hold, chosen by me:"}, {"id": "f5", "type": "textarea", "label": "What I will do in the first hour after the date has passed:"}]'::jsonb, array['PTSD and trauma', 'stabilizing', 'planning']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('trusting-anyone-means-getting-hurt-again-check-sheet', 'Trusting Anyone Means Getting Hurt Again Check Sheet', 'cbt'::resource_kind, 'A thought check sheet for the client whose rule after what happened is that trusting any person ends in harm.', 'Use it to examine the rule against the trustworthy people already in the client''s life, without arguing the past away.', array['Adults', 'Teens']::text[], '25 minutes, in session', 'A rule that no one can be trusted was learned honestly, and the client will hear any challenge to it as naivety. The sheet does not argue; it asks for the rule in the client''s words, where it came from, the people it has kept out, and then the people who have in fact been steady (a friend, a sibling, you), and what they did to earn it. A revised rule often reads: trust is earned in small steps and I get to watch. Keep the past as the rule''s origin, not as content to be written out. Watch for the client who dismisses every steady person as the exception.', '[{"id": "f0", "type": "textarea", "label": "The rule, in my own words:"}, {"id": "f1", "type": "textarea", "label": "How much I believe it today, out of 10:"}, {"id": "f2", "type": "textarea", "label": "People the rule has kept at a distance this year:"}, {"id": "f3", "type": "textarea", "label": "People who have in fact been steady with me, and what they did to show it:"}, {"id": "f4", "type": "textarea", "label": "A revised rule that keeps me safe and lets steady people in slowly:"}, {"id": "f5", "type": "textarea", "label": "How much I believe the old rule now, out of 10:"}]'::jsonb, array['PTSD and trauma', 'core beliefs', 'trust']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('memory-as-a-scrapbook-not-a-trapdoor-page', 'Memory as a Scrapbook Not a Trapdoor Page', 'act'::resource_kind, 'An ACT page that recasts a memory that drops the client into the past as a scrapbook page they can look at and close.', 'Use it to give a client an image for a memory arriving as something held in the hands rather than something fallen through.', array['Adults', 'Teens']::text[], '15 minutes, in session first', 'A memory that arrives as a trapdoor takes the client out of the room. The page offers a different image: the same memory as a page in a scrapbook, something they can hold at arm''s length, notice the edges of, and close. The client does not describe the memory''s content; they describe the cover of the book, where it sits on the shelf, what it feels like to hold it closed, and what in the room they can see while holding it. Practice with a mildly uncomfortable memory first, always in session. Watch for the client who opens the book to prove they can; the skill today is holding it closed.', '[{"id": "f0", "type": "textarea", "label": "What the cover of the scrapbook looks like, and where it sits on the shelf:"}, {"id": "f1", "type": "textarea", "label": "What it feels like in my hands when it is closed:"}, {"id": "f2", "type": "textarea", "label": "Three things I can see in this room while I hold it:"}, {"id": "f3", "type": "textarea", "label": "What tells me the trapdoor is opening, so I can reach for the book image instead:"}, {"id": "f4", "type": "textarea", "label": "One kind sentence I say to myself as I put the book back:"}, {"id": "f5", "type": "textarea", "label": "Where I will practice this next, with my therapist''s agreement:"}]'::jsonb, array['PTSD and trauma', 'metaphor', 'grounding']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('grounding-with-five-textures-in-the-coat-pocket-card', 'Grounding With Five Textures in the Coat Pocket Card', 'dbt'::resource_kind, 'A DBT grounding card built on five small textured objects kept in a coat pocket for the winter months.', 'Use it to give a client a discreet grounding kit that travels with them and can be used in a line, a car or a meeting.', array['Adults', 'Teens']::text[], 'Two minutes, whenever needed', 'A coat pocket is with the client all winter, which makes it a good place for a grounding kit: five small objects with different textures (a smooth stone, a bit of ribbon, a rough shell, a cool coin, a soft pompom). The card walks the client through finding each by touch without looking, naming its texture silently, and noticing the feet on the floor after the fifth. Assemble the kit in session so each object is chosen on purpose. Watch for the client who picks objects that carry memories; neutral textures work better here.', '[{"id": "f0", "type": "textarea", "label": "The five objects in my pocket, and the texture of each in one word:"}, {"id": "f1", "type": "textarea", "label": "The order I find them in, by touch, without looking:"}, {"id": "f2", "type": "textarea", "label": "What I noticed about my feet after the fifth object:"}, {"id": "f3", "type": "textarea", "label": "A place this week where I used the pocket without anyone knowing:"}, {"id": "f4", "type": "textarea", "label": "Which object brought me back fastest:"}, {"id": "f5", "type": "textarea", "label": "An object I will swap out, and why:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'distress tolerance']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('checking-the-locks-together-bedtime-routine-for-partners', 'Checking the Locks Together Bedtime Routine for Partners', 'couples'::resource_kind, 'A couples bedtime routine for the partner who must check every lock before sleep and the partner who finds it tiring to watch.', 'Use it to turn a solitary nightly check into a shared, time-limited routine that both partners can live with.', array['Couples']::text[], '15 minutes to plan, then nightly', 'One partner''s nightly lock check keeps them safe enough to sleep; the other watches and feels either helpless or impatient. The routine makes it shared: the partners agree on a list (doors, windows, the car), who checks what, a single walk-through together with the list read aloud once, and a closing phrase that means the house is done for tonight. The checking partner agrees the list is complete when the phrase is said; the other agrees never to roll their eyes at it. Watch for the list that grows each week; revisit it together rather than alone.', '[{"id": "f0", "type": "textarea", "label": "Checking partner: what I check each night, and what checking gives me:"}, {"id": "f1", "type": "textarea", "label": "Other partner: what it is like to watch, said without blame:"}, {"id": "f2", "type": "textarea", "label": "Our shared list, and who checks what:"}, {"id": "f3", "type": "textarea", "label": "Our closing phrase that means the house is done for tonight:"}, {"id": "f4", "type": "textarea", "label": "Checking partner: what I will do if the urge to recheck comes after the phrase:"}, {"id": "f5", "type": "textarea", "label": "Other partner: how I will respond if it does:"}]'::jsonb, array['PTSD and trauma', 'couples', 'safety']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('overpacked-suitcase-what-if-inventory-sheet', 'Overpacked Suitcase What-If Inventory Sheet', 'worksheet'::resource_kind, 'An inventory sheet for the client who packs for every possible disaster and still arrives convinced they forgot something.', 'Use it to list the what-ifs behind each extra item and decide which ones the trip actually needs answered.', array['Adults', 'Teens']::text[], '20 minutes before a trip', 'The suitcase is a map of the client''s what-ifs: the third sweater for the cold snap, the full pharmacy for the illness, the backup charger for the backup. The sheet asks the client to empty the bag onto paper, write the what-if behind each item that is not an obvious essential, rate how likely it is and how fixable it would be at the destination, and then decide what stays home. The point is not a lighter bag but a visible list of fears and their real size. Watch for the client who repacks everything the night before; have them keep the sheet in the lid.', '[{"id": "f0", "type": "textarea", "label": "Everything in the bag that is not an obvious essential:"}, {"id": "f1", "type": "textarea", "label": "The what-if behind each of those items:"}, {"id": "f2", "type": "textarea", "label": "How likely each what-if is, and how I would handle it if it happened there:"}, {"id": "f3", "type": "textarea", "label": "What I am leaving home this time, on purpose:"}, {"id": "f4", "type": "textarea", "label": "The one what-if that is worth planning for, and my plan:"}, {"id": "f5", "type": "textarea", "label": "How the trip went, and what I actually missed:"}]'::jsonb, array['anxiety', 'worry', 'planning']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('not-replying-within-the-hour-means-they-will-be-angry-sheet', 'Not Replying Within the Hour Means They Will Be Angry Sheet', 'cbt'::resource_kind, 'A probability sheet for the client who believes any delay in answering a message will cost them the relationship.', 'Use it to estimate the real odds that an hour''s silence angers anyone, and test it with one deliberate delay.', array['Adults', 'Teens']::text[], '20 minutes, then one week', 'The client who answers every message within minutes is not being polite; they are preventing a feared outcome. The sheet asks for the prediction (they will think I am ignoring them and be angry), the estimated odds, the evidence from the client''s own behavior when others take an hour, and a planned delay this week with one safe person. Then the outcome and the revised odds. Keep the delay modest, an hour or two. Watch for the client who picks the one friend who really does get angry; start with someone steady.', '[{"id": "f0", "type": "textarea", "label": "My prediction when I do not reply quickly, in detail:"}, {"id": "f1", "type": "textarea", "label": "My odds that someone is angry after an hour''s silence, out of 100:"}, {"id": "f2", "type": "textarea", "label": "What I think when other people take an hour to reply to me:"}, {"id": "f3", "type": "textarea", "label": "My planned delay this week: who, how long, and what I will do instead of checking:"}, {"id": "f4", "type": "textarea", "label": "What actually happened when I replied later:"}, {"id": "f5", "type": "textarea", "label": "My revised odds, and what I will try next:"}]'::jsonb, array['anxiety', 'predictions', 'behavioral experiment']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('anxious-mind-as-a-helicopter-parent-for-a-grown-adult-page', 'Anxious Mind as a Helicopter Parent for a Grown Adult Page', 'act'::resource_kind, 'An ACT page that pictures the anxious mind as a parent hovering over an adult child who is already competent.', 'Use it to help a client thank the hovering mind for its care and go about their day as the adult they are.', array['Adults', 'Teens']::text[], '10 minutes', 'The anxious mind hovers like a parent who has not noticed their child grew up: did you bring a coat, are you sure about that email, what if they do not like you. The page asks the client to write the mind''s hovering lines in that parental voice, notice what the hovering is trying to protect, and practice a reply an adult gives a loving but anxious parent (thanks, I have got this) before stepping out the door anyway. The tone is fond, not dismissive. Watch for the client who argues with the parent; arguing keeps them in the doorway.', '[{"id": "f0", "type": "textarea", "label": "Three things my anxious mind said to me today, written in a hovering parent''s voice:"}, {"id": "f1", "type": "textarea", "label": "What the hovering is trying to protect me from:"}, {"id": "f2", "type": "textarea", "label": "My reply, the way a grown adult answers an anxious parent they love:"}, {"id": "f3", "type": "textarea", "label": "What I did next, with the hovering still going:"}, {"id": "f4", "type": "textarea", "label": "How the hovering changed, if at all, when I stopped arguing:"}, {"id": "f5", "type": "textarea", "label": "Where I will use the reply this week:"}]'::jsonb, array['anxiety', 'defusion', 'metaphor']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('paced-breathing-while-the-oven-timer-counts-down-card', 'Paced Breathing While the Oven Timer Counts Down Card', 'dbt'::resource_kind, 'A DBT paced breathing card that uses the minutes of a kitchen timer as a built-in practice window.', 'Use it to give a client a daily, time-boxed place to slow the breath that is already in their routine.', array['Adults', 'Teens']::text[], 'Five to ten minutes, while something cooks', 'Paced breathing works best when it is practiced calm, and the wait for a timer is a window nobody uses. The card sets it up: when the oven or microwave timer starts, the client sits or leans on the counter and breathes in for four and out for six until the beep, counting on the fingers if the mind wanders. They rate tension before and after and notice what the mind did with the spare minutes. Nothing else is done in that window. Watch for the client who does the breathing while scrolling; the phone goes on the far counter.', '[{"id": "f0", "type": "textarea", "label": "How long the timer was, and what was cooking:"}, {"id": "f1", "type": "textarea", "label": "My in-count and out-count, and how many rounds I managed:"}, {"id": "f2", "type": "textarea", "label": "Tension before, out of 10, and after:"}, {"id": "f3", "type": "textarea", "label": "What my mind did with the minutes when it was not allowed to scroll:"}, {"id": "f4", "type": "textarea", "label": "A moment this week when I reached for the slow breath without a timer:"}, {"id": "f5", "type": "textarea", "label": "The next kitchen wait I will use for it:"}]'::jsonb, array['anxiety', 'breathing', 'routines']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('what-if-volleyball-serve-and-return-group-game', 'What If Volleyball Serve and Return Group Game', 'game'::resource_kind, 'A group game in which one team serves a what-if worry and the other must return it with a what-then within five seconds.', 'Use it to practice meeting a worry with a next step quickly, in a form that gets a group laughing and thinking.', array['Groups', 'Teens']::text[], '20 minutes', 'Rules: two teams face each other across a line. Team one serves a what-if (what if I miss the bus). Team two has five seconds to return a what-then (then I text that I am late and catch the next one). A good return earns a point; a return that is another what-if or a reassurance (that will not happen) loses the serve. Switch sides after five serves. Debrief: which what-ifs were hardest to return, what made a return good, and which of their own what-ifs members would now serve to themselves. Watch for a team that serves catastrophes only; keep serves to everyday worries.', '[{"id": "f0", "type": "textarea", "label": "A what-if I served:"}, {"id": "f1", "type": "textarea", "label": "The best return I heard, from either team:"}, {"id": "f2", "type": "textarea", "label": "A what-if that was hard to return, and why:"}, {"id": "f3", "type": "textarea", "label": "What made a return count as a plan rather than a brush-off:"}, {"id": "f4", "type": "textarea", "label": "A what-if of my own I will try to return this week, and my what-then:"}, {"id": "f5", "type": "textarea", "label": "How fast the five seconds felt by the end:"}]'::jsonb, array['anxiety', 'game', 'problem solving']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('low-effort-meals-from-leftovers-week-plan-sheet', 'Low Effort Meals From Leftovers Week Plan Sheet', 'worksheet'::resource_kind, 'A week plan for the client in a low stretch who has a fridge of leftovers and no energy to decide what to eat.', 'Use it to take the deciding out of feeding themselves for one week, so eating happens without a daily battle.', array['Adults']::text[], '15 minutes on the first day', 'In a low week, deciding what to eat can be the thing that stops a client eating at all. The sheet asks for what is already in the fridge and freezer, pairs it into seven low-effort meals (a plate of this and that counts), sets a time of day for each meal, and names the one person who could be asked to bring something on the worst day. It is a logistics sheet, not a food plan; there are no rules about what counts as a meal. Watch for the client who plans elaborate meals they will not cook; a sandwich written down is a sandwich eaten.', '[{"id": "f0", "type": "textarea", "label": "What is already in my fridge and freezer, in a list:"}, {"id": "f1", "type": "textarea", "label": "Seven meals I could make from that with almost no effort, one per day:"}, {"id": "f2", "type": "textarea", "label": "The time of day I will eat each one:"}, {"id": "f3", "type": "textarea", "label": "The person I could ask to bring something on the hardest day, and how I would ask:"}, {"id": "f4", "type": "textarea", "label": "What usually stops me eating in a low week, and what this plan does about it:"}, {"id": "f5", "type": "textarea", "label": "At the end of the week: how many of the seven happened, and what I would change:"}]'::jsonb, array['depression', 'routines', 'self-care']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('i-ruined-the-holiday-by-being-quiet-thought-record', 'I Ruined the Holiday by Being Quiet Thought Record', 'cbt'::resource_kind, 'A thought record for the client who sat through a gathering in low mood and has concluded their silence spoiled it for everyone.', 'Use it to test the belief that a quiet presence ruins a room, against what the other guests actually did and said.', array['Adults', 'Teens']::text[], '20 minutes', 'A client in a low stretch often attends the gathering, says little, and leaves convinced they dragged it down. The record takes the situation, the hot thought (everyone noticed, I ruined it), the mood, the evidence for and against (who talked to them, what the room was doing, how the host said goodbye), and a balanced thought. Ask what they would think of a quiet guest at their own table. Watch for the client whose evidence against is dismissed as politeness; ask how they would know the difference.', '[{"id": "f0", "type": "textarea", "label": "The gathering, and how I behaved there:"}, {"id": "f1", "type": "textarea", "label": "The hot thought, and how much I believed it when I got home:"}, {"id": "f2", "type": "textarea", "label": "Evidence that my quiet ruined the day for others:"}, {"id": "f3", "type": "textarea", "label": "Evidence that it did not (who spoke to me, what the room was doing, how I was said goodbye to):"}, {"id": "f4", "type": "textarea", "label": "What I would think of a quiet guest at my own table:"}, {"id": "f5", "type": "textarea", "label": "A balanced thought, and how much I believe it now:"}]'::jsonb, array['depression', 'thought record', 'holidays']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('low-mood-as-a-slow-internet-connection-not-a-dead-line-page', 'Low Mood as a Slow Internet Connection Not a Dead Line Page', 'act'::resource_kind, 'An ACT page that pictures a low stretch as a slow connection: everything still gets through, just later and with more patience.', 'Use it to help a client keep acting on what matters while the mood makes everything load slowly.', array['Adults', 'Teens']::text[], '10 minutes', 'In a low week, every task buffers: the reply takes an hour to send, the shower takes a morning to start. The page offers the image of a slow connection rather than a dead line; the page is loading, and refreshing in frustration does not help. The client lists what loaded slowly this week but did load, what they gave up on, and one valued thing they will keep loading tomorrow even if it takes all day. The frame is patient, not cheerful. Watch for the client who hears the metaphor as a demand to try harder; slow is allowed.', '[{"id": "f0", "type": "textarea", "label": "Things that loaded slowly this week but did load:"}, {"id": "f1", "type": "textarea", "label": "Things I gave up on because they took too long:"}, {"id": "f2", "type": "textarea", "label": "What refreshing in frustration (self-criticism) did to the loading:"}, {"id": "f3", "type": "textarea", "label": "One valued thing I will keep loading tomorrow, however slowly:"}, {"id": "f4", "type": "textarea", "label": "What patience with myself would look like, in one concrete act:"}, {"id": "f5", "type": "textarea", "label": "What I noticed about the connection speed across the week:"}]'::jsonb, array['depression', 'metaphor', 'committed action']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-declining-the-walk-invitation-card', 'Opposite Action to Declining the Walk Invitation Card', 'dbt'::resource_kind, 'A DBT opposite action card for the moment a friend suggests a short walk and the low mood says no before the client has thought.', 'Use it to help a client say yes to one small outing when the emotion''s urge to withdraw does not fit the facts.', array['Adults', 'Teens']::text[], 'One invitation, then ten minutes', 'Low mood''s urge is to decline, and declining feeds the mood. The card checks whether the urge fits the facts (is there a real reason not to go, or just the pull to stay in), and if not, the client acts opposite all the way: says yes, puts on the shoes, walks, and talks on the walk rather than enduring it. Afterward they rate the mood before, during and after, and note what the urge predicted versus what happened. Keep the outing short. Watch for the client who goes and spends the walk apologizing for being bad company.', '[{"id": "f0", "type": "textarea", "label": "The invitation, and what the urge said in the first second:"}, {"id": "f1", "type": "textarea", "label": "Did the urge fit the facts? What was the real reason to decline, if any?"}, {"id": "f2", "type": "textarea", "label": "What acting opposite all the way looked like (yes, shoes, out the door, talking):"}, {"id": "f3", "type": "textarea", "label": "Mood before, during and after, out of 10:"}, {"id": "f4", "type": "textarea", "label": "What the urge predicted, and what actually happened:"}, {"id": "f5", "type": "textarea", "label": "The next invitation I will say yes to before thinking:"}]'::jsonb, array['depression', 'opposite action', 'connection']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('carrying-the-conversation-when-one-partner-goes-quiet-plan', 'Carrying the Conversation When One Partner Goes Quiet Plan', 'couples'::resource_kind, 'A couples plan for the stretches when one partner''s low mood leaves them silent and the other does not know whether to talk, wait or leave.', 'Use it to agree in advance what the quiet partner wants from the other during a low stretch, so silence is not read as rejection.', array['Couples']::text[], 'One session, written when both are steady', 'A low stretch turns one partner quiet, and the other fills the silence with questions, cheer or distance, none of which was asked for. The plan is written when both are steady: the quiet partner says what the silence is and is not (not anger, not about you), what company they want (sitting nearby, a show on, a hand on the shoulder), what they do not want, and a word that means I am low today. The other partner says what the silence does to them and what they need in return (a check-in once a day). Both parts are kept. Watch for the plan that asks the well partner to need nothing.', '[{"id": "f0", "type": "textarea", "label": "Quiet partner: what my silence is, and what it is not:"}, {"id": "f1", "type": "textarea", "label": "Quiet partner: the company I want during a low stretch, and what I do not want:"}, {"id": "f2", "type": "textarea", "label": "Our word or signal for I am low today:"}, {"id": "f3", "type": "textarea", "label": "Other partner: what the silence does to me, and what I need in return:"}, {"id": "f4", "type": "textarea", "label": "Other partner: how I will keep the conversation light rather than fixing:"}, {"id": "f5", "type": "textarea", "label": "How we will know the low stretch is lifting, and what we will do then:"}]'::jsonb, array['depression', 'couples', 'connection']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('half-finished-craft-projects-shelf-decision-sheet', 'Half-Finished Craft Projects Shelf Decision Sheet', 'worksheet'::resource_kind, 'A decision sheet for the client whose closet holds a dozen started projects and the guilt that goes with each one.', 'Use it to sort the projects into finish, hand on or let go, and free the shelf and the client from the ones that will never be done.', array['Adults', 'Teens']::text[], '30 minutes', 'The shelf of started projects is a shelf of good intentions and a daily reminder of abandonment. The sheet lists each one, when it was started, what finishing would actually take in hours, how much the client still wants it, and a verdict: finish (with a date), hand on (to whom), or let go (how). Most clients keep two and release the rest. The sorting is the win, not the finishing. Watch for the client who marks everything finish; cap it at two and ask what the others cost them each time they open the closet.', '[{"id": "f0", "type": "textarea", "label": "Every started project on the shelf, and when I started it:"}, {"id": "f1", "type": "textarea", "label": "What finishing each one would actually take, in hours:"}, {"id": "f2", "type": "textarea", "label": "How much I still want each one, out of 10:"}, {"id": "f3", "type": "textarea", "label": "The verdict for each: finish by when, hand on to whom, or let go how:"}, {"id": "f4", "type": "textarea", "label": "What the ones I let go have been costing me each time I saw them:"}, {"id": "f5", "type": "textarea", "label": "The two I am keeping, and the first fifteen-minute step on each:"}]'::jsonb, array['ADHD', 'decisions', 'task initiation']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('forgot-the-side-dish-so-i-ruined-the-whole-meal-sheet', 'Forgot the Side Dish So I Ruined the Whole Meal Sheet', 'cbt'::resource_kind, 'A magnification sheet for the client who forgot the one dish they promised and now sees the entire meal as their failure.', 'Use it to shrink one forgotten item back to its real size among everything that went right.', array['Adults', 'Teens']::text[], '15 minutes', 'A forgotten dish, a missed text, a late arrival: the client with a slippery working memory collects these and magnifies each into a verdict. The sheet asks for the thing that was forgotten, the thought about what it meant, and then a full inventory of the event, every dish that was there, every person who ate, what anyone actually said. The forgotten item is drawn to scale beside the rest. Then a plan for next time that is a system, not a resolution to try harder. Watch for the client who converts the sheet into another self-criticism; the plan at the end is mechanical by design.', '[{"id": "f0", "type": "textarea", "label": "What I forgot, and the thought I had about what it meant:"}, {"id": "f1", "type": "textarea", "label": "Everything that was there and went fine, in a list:"}, {"id": "f2", "type": "textarea", "label": "What anyone actually said about the missing item:"}, {"id": "f3", "type": "textarea", "label": "The forgotten thing drawn to scale beside the rest: how big is it really?"}, {"id": "f4", "type": "textarea", "label": "A system for next time (a reminder, a text to myself, a check the night before), not a resolution:"}, {"id": "f5", "type": "textarea", "label": "What I will say to myself the next time I forget something small:"}]'::jsonb, array['ADHD', 'cognitive restructuring', 'self-criticism']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('attention-as-a-kite-in-gusty-wind-page', 'Attention as a Kite in Gusty Wind Page', 'act'::resource_kind, 'An ACT page that pictures attention as a kite that dips and swings in gusts, held by a hand that keeps gently pulling it back.', 'Use it to help a client see wandering attention as weather to work with rather than a character flaw.', array['Adults', 'Teens']::text[], '10 minutes', 'A kite in gusty wind is never still, and the hand on the string does not scold it; it tugs, waits, tugs again. The page asks the client to notice the gusts that pulled their attention today, how many times the hand pulled the kite back, what they said to themselves at each pull, and what a hand that simply tugs without comment would feel like. Then they try one task as the kite flyer, counting pulls without judging them. Watch for the client who counts the pulls as failures; the pulls are the skill.', '[{"id": "f0", "type": "textarea", "label": "Three gusts that pulled my attention today:"}, {"id": "f1", "type": "textarea", "label": "How many times I pulled the kite back during one task, roughly:"}, {"id": "f2", "type": "textarea", "label": "What I said to myself at each pull:"}, {"id": "f3", "type": "textarea", "label": "What a hand that only tugs, without comment, would say instead:"}, {"id": "f4", "type": "textarea", "label": "One task I will fly tomorrow, counting pulls and nothing else:"}, {"id": "f5", "type": "textarea", "label": "What I noticed when the pulls stopped being failures:"}]'::jsonb, array['ADHD', 'metaphor', 'attention']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('stop-skill-before-buying-the-gadget-that-fixes-it-all-card', 'STOP Skill Before Buying the Gadget That Fixes It All Card', 'dbt'::resource_kind, 'A DBT STOP card for the moment a new planner, app or gadget promises to solve the client''s organization for good.', 'Use it to put a pause between the promise and the purchase, so the shelf of unused systems stops growing.', array['Adults', 'Teens']::text[], 'Two minutes at the point of purchase', 'The client with a drawer of abandoned planners knows the pattern and still feels the pull of the next one. The card runs STOP at the moment the cart opens: Stop, Take a step back (close the tab for twenty-four hours), Observe (what the gadget promises, what the last three promised), Proceed mindfully (buy it tomorrow if the answer is still yes, with a plan for the first week). The point is not never buying but buying on purpose. Watch for the client who runs STOP after checkout; the card is for the cart.', '[{"id": "f0", "type": "textarea", "label": "The gadget or system, and what it promised me in the moment:"}, {"id": "f1", "type": "textarea", "label": "Stop: what I did with my hands when I noticed the pull:"}, {"id": "f2", "type": "textarea", "label": "Take a step back: the twenty-four hours, and what I did with the urge:"}, {"id": "f3", "type": "textarea", "label": "Observe: what the last three systems promised, and where they are now:"}, {"id": "f4", "type": "textarea", "label": "Proceed mindfully: my decision the next day, and if yes, my plan for its first week:"}, {"id": "f5", "type": "textarea", "label": "What I noticed about the urge when it had to wait a day:"}]'::jsonb, array['ADHD', 'STOP', 'impulses']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('timer-tower-build-until-the-beep-play', 'Timer Tower Build Until the Beep Play', 'kids'::resource_kind, 'A play in which a child builds a block tower only while a kitchen timer runs and stops at the beep, with the parent keeping time.', 'Use it to practice starting a task on cue, working through the urge to wander, and stopping when the time is up.', array['Children']::text[], '10 minutes, repeated across a week', 'Starting and stopping on cue are both hard for a child whose attention runs its own schedule, and a block tower is a task with instant feedback. The parent sets a timer for three minutes, says go, and the child builds; at the beep, hands off, no matter how tall. The pair count the blocks, and the next round the child tries to beat it. Over a week the timer grows to five minutes. The parent praises the stop as much as the height. Watch for the child who melts down at the beep; shorten the time until the stop is easy, then grow it.', '[{"id": "f0", "type": "textarea", "label": "How tall my tower got before the beep today:"}, {"id": "f1", "type": "textarea", "label": "What I wanted to do when the beep went, and what I did instead:"}, {"id": "f2", "type": "textarea", "label": "Something that tried to pull me away while I was building:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up said about my stop:"}, {"id": "f4", "type": "textarea", "label": "Tomorrow''s timer, and the number of blocks I am aiming for:"}, {"id": "f5", "type": "textarea", "label": "Another task where I could use the go and the beep:"}]'::jsonb, array['ADHD', 'children', 'play']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('leftover-wine-on-the-counter-after-guests-leave-plan-sheet', 'Leftover Wine on the Counter After Guests Leave Plan Sheet', 'worksheet'::resource_kind, 'A planning sheet for the hours after a gathering when open bottles sit on the counter and the client is tired, alone and tempted.', 'Use it to decide before the party what happens to the leftovers, who helps, and how the first quiet hour is spent.', array['Adults']::text[], '15 minutes before hosting', 'The party itself has a plan; the hour after rarely does, and that is when the half-full bottles on the counter do their work. The sheet decides in advance: what happens to opened bottles and when (poured out, sent home with a guest, boxed by a partner before the goodbyes), who in the house does it, what the client does with the first quiet hour instead (dishes with music, a shower, a call), and the number they would text if the urge climbs. Write it as logistics, not willpower. Watch for the client who plans to just not drink the leftovers; the plan removes them.', '[{"id": "f0", "type": "textarea", "label": "What happens to every opened bottle before the last guest leaves, and who does it:"}, {"id": "f1", "type": "textarea", "label": "What I will do with the first quiet hour after the door closes:"}, {"id": "f2", "type": "textarea", "label": "How tired I expect to be, and what tired does to my urges:"}, {"id": "f3", "type": "textarea", "label": "The person I will text if the urge climbs, and what I will say:"}, {"id": "f4", "type": "textarea", "label": "What I will have in my hand while cleaning up:"}, {"id": "f5", "type": "textarea", "label": "How the night went, and what I would change for the next gathering:"}]'::jsonb, array['addiction', 'substance use', 'planning']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('i-earned-one-after-all-that-cooking-permission-thought-sheet', 'I Earned One After All That Cooking Permission Thought Sheet', 'cbt'::resource_kind, 'A permission thought sheet for the client who frames substance use as a reward owed for a long day of effort.', 'Use it to catch the earned-it thought as a thought, test it, and find what the effort actually deserves.', array['Adults']::text[], '15 minutes, then one hard day', 'The earned-it thought is one of the most persuasive permission thoughts because the effort behind it is real. The sheet asks the client to write it exactly as it arrives, name what the day actually cost them, what the use would give and take, what a reward that did not undo the day would look like, and a reply in their own words for the next time. Keep the effort honored; the question is the reward, not whether they worked hard. Watch for the client who picks a replacement reward they do not actually want; it has to be something they would choose.', '[{"id": "f0", "type": "textarea", "label": "The permission thought exactly as it arrived (I earned one after all that):"}, {"id": "f1", "type": "textarea", "label": "What the day actually cost me, honestly:"}, {"id": "f2", "type": "textarea", "label": "What using would give me tonight, and what it would take by tomorrow:"}, {"id": "f3", "type": "textarea", "label": "A reward that honors the effort without undoing the day:"}, {"id": "f4", "type": "textarea", "label": "My reply to the thought, in my own words, for next time:"}, {"id": "f5", "type": "textarea", "label": "What I did on the next hard day, and how the reward landed:"}]'::jsonb, array['addiction', 'urges', 'permission thoughts']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('urge-as-a-pop-up-window-i-close-without-reading-page', 'Urge as a Pop-Up Window I Close Without Reading Page', 'act'::resource_kind, 'An ACT page that treats the urge to use as a pop-up window: it appears without being asked and can be closed without being argued with.', 'Use it to give a client a quick, unglamorous image for letting an urge appear and pass without engaging its offer.', array['Adults']::text[], '10 minutes, then as urges arrive', 'Pop-up windows are not reasoned with; they are closed. The page asks the client to notice how an urge pops up (the moment, the pitch, the special offer), to write its text as a pop-up would show it, to notice the urge to read the fine print, and to practice the click: a phrase or a motion that closes it and returns them to what they were doing. They log how many pop-ups appeared this week and how many were closed without reading. Watch for the client who treats closing as defeating; pop-ups come back, and that is not failure.', '[{"id": "f0", "type": "textarea", "label": "The urge written as pop-up text, with its special offer:"}, {"id": "f1", "type": "textarea", "label": "What tends to make the pop-up appear (the moment, the mood, the place):"}, {"id": "f2", "type": "textarea", "label": "My click: the phrase or motion that closes it:"}, {"id": "f3", "type": "textarea", "label": "What I returned to after closing it:"}, {"id": "f4", "type": "textarea", "label": "How many pop-ups this week, and how many I closed without reading:"}, {"id": "f5", "type": "textarea", "label": "What I noticed about the pop-ups when I stopped arguing with them:"}]'::jsonb, array['addiction', 'urges', 'defusion']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('cope-ahead-for-the-long-weekend-with-no-structure-card', 'Cope Ahead for the Long Weekend With No Structure Card', 'dbt'::resource_kind, 'A DBT cope ahead card for the open days of a long weekend, when the usual routine disappears and urges fill the space.', 'Use it to rehearse the empty hours in advance, with a plan for each and a skill ready for the hardest one.', array['Adults']::text[], '20 minutes before the weekend', 'A long weekend removes the structure that has been holding the client''s week together, and the empty afternoon is where urges show up. The card walks through cope ahead: describe the situation in detail (Saturday 3 p.m., alone, nothing planned), name the emotions and urges likely to appear, decide the skills to use and the plan for the hours, then rehearse it in imagination, including the moment the plan goes wrong. Build in people and movement. Watch for the client who fills every hour; some rest is part of the plan, and rest with a skill ready is different from a void.', '[{"id": "f0", "type": "textarea", "label": "The hours of the weekend most likely to be hard, in detail:"}, {"id": "f1", "type": "textarea", "label": "The emotions and urges I expect in those hours:"}, {"id": "f2", "type": "textarea", "label": "My plan for each hard hour (where, with whom, doing what):"}, {"id": "f3", "type": "textarea", "label": "The skill I will use if the urge climbs anyway:"}, {"id": "f4", "type": "textarea", "label": "My rehearsal: what I pictured, including the moment the plan went wrong and what I did:"}, {"id": "f5", "type": "textarea", "label": "After the weekend: which hour was hardest, and what worked:"}]'::jsonb, array['addiction', 'cope ahead', 'urges']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('partner-who-still-drinks-shared-home-boundaries-talk-sheet', 'Partner Who Still Drinks Shared Home Boundaries Talk Sheet', 'couples'::resource_kind, 'A couples talk sheet for the partner who has stopped drinking and the partner who has not, living under one roof.', 'Use it to agree what alcohol does and does not do in the shared home, with both partners'' needs on the page.', array['Couples']::text[], 'One session', 'One partner has stopped; the other drinks moderately and does not want their own habits policed. The house has to hold both. The sheet asks the sober partner what in the home makes the early weeks harder (bottles in view, a glass poured at dinner, the smell), the drinking partner what they are and are not willing to change and what they fear being asked for, and then the agreements: where alcohol is kept, when it is used, what is said about it, and how either partner raises a problem. Watch for the sheet that reads as one partner''s rules; each gives and each gets.', '[{"id": "f0", "type": "textarea", "label": "Sober partner: what in our home makes the early stretch harder, specifically:"}, {"id": "f1", "type": "textarea", "label": "Drinking partner: what I am willing to change, and what I am afraid of being asked:"}, {"id": "f2", "type": "textarea", "label": "Where alcohol is kept and when it is used in our home, agreed by both:"}, {"id": "f3", "type": "textarea", "label": "What we say about it, and what we do not say, in front of each other and guests:"}, {"id": "f4", "type": "textarea", "label": "How either of us raises a problem with the agreement:"}, {"id": "f5", "type": "textarea", "label": "When we will revisit this, and what would tell us it needs changing:"}]'::jsonb, array['addiction', 'couples', 'substance use']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('morning-after-the-blowup-review-and-next-step-sheet', 'Morning After the Blowup Review and Next Step Sheet', 'worksheet'::resource_kind, 'A morning-after sheet for the client who lost their temper last night and wakes to the shame and the mess.', 'Use it to review the blowup as a chain of events, choose one repair and one change, and leave the self-punishment out.', array['Adults', 'Teens']::text[], '20 minutes the next morning', 'The morning after an outburst, the client either rewrites it as justified or sinks into shame, and neither helps. The sheet walks the chain: what the day held before the trigger, the trigger, the first body sign, the thought that lit it, what was said, what happened after. Then one repair that can be made today in a sentence, and one change at the earliest link in the chain. Keep the sheet factual; the shame does not get a column. Watch for the client who skips the repair and goes straight to the change; the repair comes first.', '[{"id": "f0", "type": "textarea", "label": "What the day held before the blowup (tired, hungry, already stewing):"}, {"id": "f1", "type": "textarea", "label": "The trigger, and the first sign in my body:"}, {"id": "f2", "type": "textarea", "label": "The thought that lit it:"}, {"id": "f3", "type": "textarea", "label": "What I said or did, and what happened in the hour after:"}, {"id": "f4", "type": "textarea", "label": "One repair I can make today, in one sentence:"}, {"id": "f5", "type": "textarea", "label": "One change at the earliest link in the chain for next time:"}]'::jsonb, array['anger management', 'repair', 'chain analysis']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('if-i-do-not-yell-nobody-listens-belief-sheet', 'If I Do Not Yell Nobody Listens Belief Sheet', 'cbt'::resource_kind, 'A belief sheet for the client who has learned that volume gets results and quiet gets ignored.', 'Use it to test the belief against what yelling actually gets and loses, and try one firm quiet request.', array['Adults', 'Teens']::text[], '20 minutes, then one week', 'The belief is often half true: yelling does get a reaction. The sheet asks for the belief, the evidence for it, what the reaction actually is (compliance, fear, distance), what it costs afterward, and the times a quiet firm request did work. Then one experiment: a request made once, low and clear, with a planned follow-up if it is not met. The outcome gets recorded without spin. Watch for the client who whispers the request and calls it quiet; firm and quiet is the target.', '[{"id": "f0", "type": "textarea", "label": "The belief, in my words, and how much I believe it:"}, {"id": "f1", "type": "textarea", "label": "Evidence that yelling gets me heard:"}, {"id": "f2", "type": "textarea", "label": "What the reaction to yelling actually is, and what it costs me afterward:"}, {"id": "f3", "type": "textarea", "label": "A time a quiet, firm request worked, with anyone:"}, {"id": "f4", "type": "textarea", "label": "My experiment this week: the request, said once, low and clear, and my follow-up if ignored:"}, {"id": "f5", "type": "textarea", "label": "What happened, and how much I believe the belief now:"}]'::jsonb, array['anger management', 'core beliefs', 'assertiveness']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('anger-as-a-car-horn-stuck-on-page', 'Anger as a Car Horn Stuck On Page', 'act'::resource_kind, 'An ACT page that pictures anger that will not let up as a car horn jammed on, loud, pointless and not fixable by pressing harder.', 'Use it to help a client step back from a stuck anger and choose what to do with their hands while the horn blares.', array['Adults', 'Teens']::text[], '10 minutes', 'Some anger does not pass; it sits in the chest for hours like a horn jammed on in a parking lot. Pressing the horn harder (rehearsing the grievance) does nothing. The page asks the client to describe the horn (where it sounds, what it keeps saying), notice the urge to press harder, and choose what to do with their hands and feet while it blares: a walk, a task, a call about something else. The horn stops when it stops. Watch for the client who wants an image that silences the anger; this one is about living beside it.', '[{"id": "f0", "type": "textarea", "label": "Where the horn sounds in my body, and what it keeps saying:"}, {"id": "f1", "type": "textarea", "label": "What pressing harder looks like for me (rehearsing, replaying, telling it again):"}, {"id": "f2", "type": "textarea", "label": "What pressing harder has done to the volume:"}, {"id": "f3", "type": "textarea", "label": "What I will do with my hands and feet while it blares:"}, {"id": "f4", "type": "textarea", "label": "How long the horn ran this time, and what finally let it stop:"}, {"id": "f5", "type": "textarea", "label": "What I want to remember about the horn next time it jams:"}]'::jsonb, array['anger management', 'metaphor', 'acceptance']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('willing-hands-at-the-family-table-debate-card', 'Willing Hands at the Family Table Debate Card', 'dbt'::resource_kind, 'A DBT willing hands card for the moment the table talk turns to the topic that makes the client''s fists close under the cloth.', 'Use it to change the body''s stance before the words come, so the client can choose what to say or not say.', array['Adults', 'Teens']::text[], 'One meal', 'Fists under the table send the signal that a fight has started before anyone has spoken. Willing hands reverses it: palms up on the thighs or open on the table, fingers loose, shoulders dropped, while the relative holds forth. The card asks the client to practice the posture in session, pick a cue (the first tight jaw), hold the hands open for a full minute before deciding whether to speak, and notice what the open hands do to the urge to interrupt. Watch for the client who opens the hands and clenches the jaw; add a half smile.', '[{"id": "f0", "type": "textarea", "label": "The topic and the person that bring my fists closed:"}, {"id": "f1", "type": "textarea", "label": "My cue to open my hands (the first sign in my body):"}, {"id": "f2", "type": "textarea", "label": "What willing hands looked like at the table, and for how long I held them:"}, {"id": "f3", "type": "textarea", "label": "What the open hands did to the urge to interrupt or argue:"}, {"id": "f4", "type": "textarea", "label": "What I chose to say, or not say, after the minute:"}, {"id": "f5", "type": "textarea", "label": "How the rest of the meal went compared with last time:"}]'::jsonb, array['anger management', 'willing hands', 'distress tolerance']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('count-to-ten-in-silly-voices-cool-down-game', 'Count to Ten in Silly Voices Cool Down Game', 'game'::resource_kind, 'A cool-down game in which players count to ten in a new silly voice each round, so the pause before reacting becomes fun.', 'Use it to make the count-to-ten pause playful enough that a young person or a group will actually reach for it when hot.', array['Children', 'Groups']::text[], '10 minutes', 'Rules: players sit in a circle. The leader names a voice (robot, whisper, opera singer, sleepy bear) and the group counts to ten together in that voice, one number each around the circle. Anyone who laughs out of turn picks the next voice. Three rounds, then a challenge round: the leader describes a mildly annoying moment (someone took your seat) and the group counts to ten in the voice of their choice before saying what they would do. Debrief: which voice slowed you down most, and which one you would use in real life. Watch for a group that counts fast; the count is slow or it does not count.', '[{"id": "f0", "type": "textarea", "label": "The voice that slowed me down most:"}, {"id": "f1", "type": "textarea", "label": "The voice I laughed at the most:"}, {"id": "f2", "type": "textarea", "label": "In the challenge round, what I would do after the count:"}, {"id": "f3", "type": "textarea", "label": "A real moment this week when I could count to ten in a voice:"}, {"id": "f4", "type": "textarea", "label": "Which voice I would pick for it:"}, {"id": "f5", "type": "textarea", "label": "Who I could teach the game to at home:"}]'::jsonb, array['anger management', 'game', 'regulation']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('asking-the-search-bar-for-reassurance-log-sheet', 'Asking the Search Bar for Reassurance Log Sheet', 'worksheet'::resource_kind, 'A log for the client who types the same worried question into a search engine several times a day to feel briefly certain.', 'Use it to count the searches, note what each one bought and for how long, and choose a delay before the next.', array['Adults', 'Teens']::text[], 'One week', 'Searching is reassurance seeking with no one to notice it, so it can run fifty times a day unremarked. The log asks for each search (or a tally when they blur together), the doubt that sent the client to the bar, how certain they felt right after, out of 10, how long that lasted, and the doubt''s return. After three days the client adds a delay rule (ten minutes, then an hour) and logs what the doubt did while it waited. Watch for the client who logs honestly and then searches to check they logged correctly; that one goes in the log too.', '[{"id": "f0", "type": "textarea", "label": "The question I keep searching, in its most common wording:"}, {"id": "f1", "type": "textarea", "label": "Today''s tally, and the doubt behind the first search:"}, {"id": "f2", "type": "textarea", "label": "How certain I felt right after searching, out of 10, and how long it lasted:"}, {"id": "f3", "type": "textarea", "label": "My delay rule for tomorrow, and what I will do during the wait:"}, {"id": "f4", "type": "textarea", "label": "What the doubt did while it waited:"}, {"id": "f5", "type": "textarea", "label": "What the week''s log tells me about what searching buys:"}]'::jsonb, array['OCD', 'reassurance', 'monitoring']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('feeling-unsure-means-something-is-wrong-belief-check-sheet', 'Feeling Unsure Means Something Is Wrong Belief Check Sheet', 'cbt'::resource_kind, 'A belief check sheet for the client who treats the feeling of uncertainty itself as proof that a mistake was made.', 'Use it to separate the feeling of not-sure from the fact of a problem, with examples from ordinary life.', array['Adults', 'Teens']::text[], '20 minutes', 'The belief that unsure equals wrong turns every ordinary doubt into an alarm. The sheet asks for the belief, then a list of times the client felt sure and was wrong and times they felt unsure and everything was fine (did I lock it, did I send it, did I say the right thing), what the feeling of not-sure is physically, and whether other people act on that feeling the same way. A revised belief often reads: not-sure is a feeling, and feelings are not reports. Watch for the client who wants a rule for when unsure does mean wrong; the point is that the feeling cannot tell them.', '[{"id": "f0", "type": "textarea", "label": "The belief, in my words, and how much I believe it:"}, {"id": "f1", "type": "textarea", "label": "Times I felt sure and was wrong:"}, {"id": "f2", "type": "textarea", "label": "Times I felt unsure and everything was fine:"}, {"id": "f3", "type": "textarea", "label": "What not-sure feels like in my body, as a sensation rather than a verdict:"}, {"id": "f4", "type": "textarea", "label": "How the people I trust act when they feel not-sure:"}, {"id": "f5", "type": "textarea", "label": "A revised belief about the feeling, and how much I believe it now:"}]'::jsonb, array['OCD', 'uncertainty', 'core beliefs']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('doubt-as-a-pop-quiz-i-decline-to-take-page', 'Doubt as a Pop Quiz I Decline to Take Page', 'act'::resource_kind, 'An ACT page that pictures the recurring doubt as a surprise quiz handed out by the mind, which the client can decline to sit.', 'Use it to help a client notice the quiz being handed out and put the pencil down rather than fill it in again.', array['Adults', 'Teens']::text[], '10 minutes, then as doubts arrive', 'The mind hands out the same quiz all day: are you sure, did you really, what if you did not. Each time the client fills it in they sit another exam with no passing grade. The page asks the client to write the quiz''s questions as they appear, notice the urge to pick up the pencil, and practice declining: a sentence that returns the paper (not taking this one today) and the thing they turn back to. They log how many quizzes were handed out and how many they declined. Watch for the client who declines by arguing the questions are unfair; declining is quieter than that.', '[{"id": "f0", "type": "textarea", "label": "The quiz questions my mind hands me most, written as they appear:"}, {"id": "f1", "type": "textarea", "label": "What picking up the pencil looks like for me (reviewing, checking, asking):"}, {"id": "f2", "type": "textarea", "label": "My declining sentence, and what I turn back to after saying it:"}, {"id": "f3", "type": "textarea", "label": "How many quizzes today, and how many I declined:"}, {"id": "f4", "type": "textarea", "label": "What the mind did when the paper came back blank:"}, {"id": "f5", "type": "textarea", "label": "Where I will practice declining next:"}]'::jsonb, array['OCD', 'defusion', 'uncertainty']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('willing-hands-past-the-crooked-picture-frame-card', 'Willing Hands Past the Crooked Picture Frame Card', 'dbt'::resource_kind, 'A DBT willing hands card for walking past a picture frame hanging slightly off and leaving it that way on purpose.', 'Use it to practice tolerating the not-right feeling with an open body rather than a straightening hand.', array['Adults', 'Teens']::text[], 'Daily for a week', 'The crooked frame pulls the hand toward it a dozen times a day, and each straightening teaches the body that not-right cannot be left. The card asks the client to tilt one frame slightly, on purpose, and each time they pass it to open the hands (palms up or relaxed at the sides), drop the shoulders, breathe once and keep walking. They log the urge out of 10 at the first pass, the twentieth and the end of the week. Choose a frame in a room the client uses. Watch for the client who straightens it at bedtime to sleep; that is the moment the card is for.', '[{"id": "f0", "type": "textarea", "label": "The frame I tilted, and how it felt to tilt it on purpose:"}, {"id": "f1", "type": "textarea", "label": "What willing hands looked like as I passed it:"}, {"id": "f2", "type": "textarea", "label": "Urge to straighten at the first pass, out of 10:"}, {"id": "f3", "type": "textarea", "label": "Urge at the twentieth pass, roughly:"}, {"id": "f4", "type": "textarea", "label": "The hardest moment of the week to leave it, and what I did:"}, {"id": "f5", "type": "textarea", "label": "Urge at the end of the week, and what I want to tilt next:"}]'::jsonb, array['OCD', 'willing hands', 'distress tolerance']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('uh-oh-thought-return-to-sender-mailbox-craft', 'Uh-Oh Thought Return to Sender Mailbox Craft', 'kids'::resource_kind, 'A craft in which a child builds a small mailbox marked Return to Sender for the uh-oh thoughts the brain keeps delivering.', 'Use it to give a child a playful way to notice a sticky thought, decide it is junk mail, and send it back without obeying it.', array['Children']::text[], '30 minutes to make, then daily', 'A tissue box, paint and a flap make a mailbox; the child paints Return to Sender on the side. The parent explains that some thoughts arrive like junk mail, loud and bossy (you have to check, you have to wash again, what if), and the child''s job is not to do what the mail says but to write or draw it on a slip and post it back. Once a day the parent and child empty the box together and count the returns without reading them aloud. The parent returns one of their own junk thoughts first. Watch for the child who wants to reread the slips; they go back unread, that is the rule.', '[{"id": "f0", "type": "textarea", "label": "What my mailbox looks like, and what I painted on it:"}, {"id": "f1", "type": "textarea", "label": "A bossy thought I returned today, drawn or written on a slip:"}, {"id": "f2", "type": "textarea", "label": "What the thought wanted me to do, and what I did instead:"}, {"id": "f3", "type": "textarea", "label": "How many returns were in the box when we emptied it:"}, {"id": "f4", "type": "textarea", "label": "A junk thought my grown-up returned:"}, {"id": "f5", "type": "textarea", "label": "Where my mailbox lives so I can post fast:"}]'::jsonb, array['OCD', 'children', 'craft']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('window-seat-on-the-long-haul-flight-surge-plan-sheet', 'Window Seat on the Long-Haul Flight Surge Plan Sheet', 'worksheet'::resource_kind, 'A plan sheet for the client taking a long flight who fears a surge in a window seat with two strangers between them and the aisle.', 'Use it to settle the seat choice, the in-seat tools and the words for the neighbor, so the flight is a plan rather than a trap.', array['Adults', 'Teens']::text[], '20 minutes before booking or flying', 'A long flight concentrates the client''s fears: nowhere to go, nobody to tell, hours to wait. The sheet works through seat choice (aisle versus window, with the real trade-offs), what the client can do in a seat without moving (paced breath, cold water, a texture, a film), the sentence they would say to a neighbor if they needed to stand, what they will tell themselves at the first flutter, and a timeline for the flight broken into thirty-minute chunks with something planned for each. Watch for the client who plans to avoid sleep so they can stay on guard; sleep is in the plan.', '[{"id": "f0", "type": "textarea", "label": "The seat I will choose, and the honest trade-offs:"}, {"id": "f1", "type": "textarea", "label": "Three things I can do in my seat without moving:"}, {"id": "f2", "type": "textarea", "label": "The sentence I would say to my neighbor if I needed to stand:"}, {"id": "f3", "type": "textarea", "label": "What I will tell myself at the first flutter:"}, {"id": "f4", "type": "textarea", "label": "The flight in thirty-minute chunks, with something for each:"}, {"id": "f5", "type": "textarea", "label": "How I will handle the stretch when the seatbelt sign is on and I cannot get up:"}]'::jsonb, array['panic attacks', 'planning', 'travel']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('tingling-hands-mean-a-stroke-fact-check-sheet', 'Tingling Hands Mean a Stroke Fact Check Sheet', 'cbt'::resource_kind, 'A fact check sheet for the client whose surge brings tingling fingers and the certainty that something is wrong with their brain.', 'Use it to lay out what the client knows about the tingling, test the catastrophic read, and plan what to do with the hands next time.', array['Adults', 'Teens']::text[], '20 minutes, in session', 'Tingling in the hands during a surge is a frightening sensation that the catastrophic mind reads fast. The sheet asks for the sensation as the client feels it, the thought it triggers, the evidence for that thought, the other explanations they have heard from their physician or learned (fast breathing, gripping, adrenaline), what has happened every previous time, and what their doctor has said. Then a plan for the hands next time: open them, shake them, breathe slowly, time it. Watch for the client who checks the sensation hourly to see if it has come back.', '[{"id": "f0", "type": "textarea", "label": "The tingling as I feel it, where and how it starts:"}, {"id": "f1", "type": "textarea", "label": "The thought it triggers, and how sure I feel in the moment, out of 10:"}, {"id": "f2", "type": "textarea", "label": "Evidence for the thought:"}, {"id": "f3", "type": "textarea", "label": "Other explanations I have been given, and what has happened every previous time:"}, {"id": "f4", "type": "textarea", "label": "What my doctor has told me, in their words:"}, {"id": "f5", "type": "textarea", "label": "My plan for my hands at the first tingle next time, and how long I will give it:"}]'::jsonb, array['panic attacks', 'fact check', 'body sensations']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('panic-as-an-express-train-passing-the-platform-page', 'Panic as an Express Train Passing the Platform Page', 'act'::resource_kind, 'An ACT page that pictures a surge as an express train roaring through the station without stopping, loud and then gone.', 'Use it to give a client an image for standing still on the platform while the surge passes rather than running from it.', array['Adults', 'Teens']::text[], '10 minutes, then as needed', 'An express train is terrifying from the platform and over in seconds. The page asks the client to describe their surge as a train (the rumble that comes first, the roar, the wind, the quiet after), to notice what running down the platform does (it is still loud, and now they are out of breath), and to practice standing still with a hand on the railing, feet planted, while it passes. They record how long the train took and what the quiet after was like. Watch for the client who times it as a test they could fail; timing is for noticing that it ends.', '[{"id": "f0", "type": "textarea", "label": "My surge as a train: the rumble, the roar, the wind, the quiet after:"}, {"id": "f1", "type": "textarea", "label": "What running down the platform (fighting, fleeing, checking) has done in the past:"}, {"id": "f2", "type": "textarea", "label": "My railing: the thing I hold or plant while it passes:"}, {"id": "f3", "type": "textarea", "label": "How long the last train took, timed:"}, {"id": "f4", "type": "textarea", "label": "What the quiet after was like:"}, {"id": "f5", "type": "textarea", "label": "What I will say to myself when I hear the next rumble:"}]'::jsonb, array['panic attacks', 'metaphor', 'acceptance']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('paced-breathing-while-the-elevator-climbs-ten-floors-card', 'Paced Breathing While the Elevator Climbs Ten Floors Card', 'dbt'::resource_kind, 'A DBT paced breathing card for the client whose heart races in elevators, using the floor count as the breath''s rhythm.', 'Use it to turn a short, trapped ride into a timed breathing practice with a visible countdown.', array['Adults', 'Teens']::text[], 'One ride at a time', 'The elevator is short, trapped and full of mirrors, and the heart knows it. The card gives the ride a structure: breathe in for one floor, out for two, watching the numbers change, hands loose at the sides, eyes on the display rather than the door. On arrival the client rates the surge, out of 10, and notes how many floors the breath lasted. Then the next ride. The counting replaces the checking. Watch for the client who takes the stairs to avoid the practice; a two-floor ride is a fine start.', '[{"id": "f0", "type": "textarea", "label": "How many floors, and what my body did in the first second the doors closed:"}, {"id": "f1", "type": "textarea", "label": "My rhythm: in for one floor, out for two, and how many rounds that gave me:"}, {"id": "f2", "type": "textarea", "label": "Where my eyes and hands were during the ride:"}, {"id": "f3", "type": "textarea", "label": "Surge on arrival, out of 10:"}, {"id": "f4", "type": "textarea", "label": "The ride where the breath lasted the whole way:"}, {"id": "f5", "type": "textarea", "label": "The next building I will try it in:"}]'::jsonb, array['panic attacks', 'breathing', 'distress tolerance']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('jitters-on-purpose-shake-and-still-group-game', 'Jitters on Purpose Shake and Still Group Game', 'game'::resource_kind, 'A group game in which players shake their whole body for thirty seconds on cue, freeze, and name what the body does in the stillness after.', 'Use it to let a group feel adrenaline sensations as something they can make and watch pass, with laughter in the room.', array['Groups', 'Teens']::text[], '15 minutes', 'Rules: the leader calls shake and everyone shakes hands, arms, legs and shoulders as hard as they can for thirty seconds. On freeze, everyone stands still and silent for thirty seconds, noticing the heart, the breath and the buzzing in the limbs. Then each player names one sensation in one word, around the circle. Three rounds, the last with eyes closed in the freeze. Debrief: how the sensations compared with a surge, how long they took to settle, and what it was like to make them on purpose. Watch for the member who stops early in the shake; the point is to reach the buzz.', '[{"id": "f0", "type": "textarea", "label": "The one word I said after round one:"}, {"id": "f1", "type": "textarea", "label": "What my heart and breath did in the freeze, and how long before they settled:"}, {"id": "f2", "type": "textarea", "label": "How the sensations compared with a surge I have had:"}, {"id": "f3", "type": "textarea", "label": "What it was like to make them on purpose, with other people:"}, {"id": "f4", "type": "textarea", "label": "Round three with eyes closed: what changed:"}, {"id": "f5", "type": "textarea", "label": "A sensation I am less afraid of after the game:"}]'::jsonb, array['panic attacks', 'game', 'body sensations']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('relatives-who-tease-my-kid-response-plan-sheet', 'Relatives Who Tease My Kid Response Plan Sheet', 'worksheet'::resource_kind, 'A response plan for the parent whose relatives tease their child at gatherings in ways the child does not enjoy.', 'Use it to script what the parent says in the moment, what they say to the child after, and what they decide before the next visit.', array['Adults']::text[], '20 minutes before a gathering', 'A grandparent''s teasing is affection to the grandparent and a public sting to the child, and the parent is caught in the middle. The sheet asks which relative, the usual line, what the child''s face does, a one-sentence redirect the parent can say warmly in the moment (she does not love that one, tell her about your trip instead), what the parent says to the child in private afterward, and whether a conversation with the relative is needed before next time. Rehearse the redirect aloud. Watch for the parent who plans a confrontation at the table; the redirect first, the conversation later.', '[{"id": "f0", "type": "textarea", "label": "Who teases, and the line they usually use:"}, {"id": "f1", "type": "textarea", "label": "What my child''s face and body do when it happens:"}, {"id": "f2", "type": "textarea", "label": "My one-sentence redirect for the moment, said warmly:"}, {"id": "f3", "type": "textarea", "label": "What I will say to my child afterward, in private:"}, {"id": "f4", "type": "textarea", "label": "Whether I need a conversation with the relative before the next visit, and the first line of it:"}, {"id": "f5", "type": "textarea", "label": "How it went, and what my child said about it later:"}]'::jsonb, array['parenting', 'family', 'boundaries']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('if-i-lose-my-temper-once-i-have-damaged-them-for-good-sheet', 'If I Lose My Temper Once I Have Damaged Them for Good Sheet', 'cbt'::resource_kind, 'A thought record for the parent who snapped at their child and is certain the moment did permanent harm.', 'Use it to test the all-or-nothing read of one hard moment against the repair that followed and the whole relationship around it.', array['Adults']::text[], '20 minutes', 'A parent who yelled at bedtime can spend the night certain they have broken something. The record takes the moment, the hot thought (I have damaged them for good), the evidence for it, and the evidence against: the repair they made or could make, what the child did the next morning, what the client knows about the relationship across the whole week. A balanced thought often lands on: one hard moment plus a repair is what children learn from. Watch for the client who uses the record to rehearse the yelling; keep the retelling to one line and spend the time on the repair.', '[{"id": "f0", "type": "textarea", "label": "The moment, in one line:"}, {"id": "f1", "type": "textarea", "label": "The hot thought, and how much I believed it that night:"}, {"id": "f2", "type": "textarea", "label": "Evidence that one moment caused lasting harm:"}, {"id": "f3", "type": "textarea", "label": "Evidence against it: the repair I made or could make, what my child did the next morning:"}, {"id": "f4", "type": "textarea", "label": "What the whole week between us actually looked like:"}, {"id": "f5", "type": "textarea", "label": "A balanced thought I can keep for the next hard bedtime:"}]'::jsonb, array['parenting', 'thought record', 'repair']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('values-when-my-child-lies-about-the-broken-lamp-page', 'Values When My Child Lies About the Broken Lamp Page', 'act'::resource_kind, 'An ACT values page for the parent standing over a broken lamp and a child who says they did not do it.', 'Use it to choose the parent the client wants to be in the moment of a lie, before the moment arrives again.', array['Adults']::text[], '15 minutes', 'A child''s lie pulls hard on a parent''s fear (what are they becoming) and anger (they looked me in the eye), and the response that follows is rarely the one the parent would choose. The page asks what the parent felt in the moment, what the fear said, what they value about honesty and about their child feeling safe enough to tell the truth, and what a response that served both would sound like. Then a sentence for the next lie. Watch for the parent who values honesty so fiercely that the child learns only to lie better; the safe-enough value needs equal room.', '[{"id": "f0", "type": "textarea", "label": "What I felt the moment my child lied, and what the fear said about who they will become:"}, {"id": "f1", "type": "textarea", "label": "What I value about honesty in our family:"}, {"id": "f2", "type": "textarea", "label": "What I value about my child feeling safe enough to tell me hard things:"}, {"id": "f3", "type": "textarea", "label": "A response to the lamp that would have served both values:"}, {"id": "f4", "type": "textarea", "label": "My sentence for the next lie (I think something happened here; you can tell me and we will fix it together):"}, {"id": "f5", "type": "textarea", "label": "What I want my child to remember about how I handled it:"}]'::jsonb, array['parenting', 'values', 'honesty']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('validation-when-my-child-says-school-is-boring-card', 'Validation When My Child Says School Is Boring Card', 'dbt'::resource_kind, 'A DBT validation card for the daily complaint that school is boring, before the parent reaches for a lecture about effort.', 'Use it to practice validating what is valid in the complaint and then asking a real question, with the lecture left in the drawer.', array['Adults']::text[], 'Five minutes, after school', 'School is boring is often the first line of something the child cannot yet say, and the lecture ends the conversation before the second line arrives. The card asks the parent to validate what is valid (sitting still for six hours is long), ask one curious question (which part was the longest), and resist the urge to fix or correct for one whole exchange. Afterward they note what the second line turned out to be. Watch for the parent who validates and then adds but; the but undoes the validation.', '[{"id": "f0", "type": "textarea", "label": "What my child said, and the lecture that rose in me:"}, {"id": "f1", "type": "textarea", "label": "What was valid in the complaint, said back to them in one sentence:"}, {"id": "f2", "type": "textarea", "label": "The curious question I asked instead of correcting:"}, {"id": "f3", "type": "textarea", "label": "What the second line turned out to be:"}, {"id": "f4", "type": "textarea", "label": "How long I managed without a but:"}, {"id": "f5", "type": "textarea", "label": "What I learned about their day that the lecture would have missed:"}]'::jsonb, array['parenting', 'validation', 'interpersonal effectiveness']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('family-thank-you-chain-add-a-link-a-day-craft', 'Family Thank You Chain Add a Link a Day Craft', 'kids'::resource_kind, 'A craft in which a family adds one paper link a day to a chain across the kitchen, each naming something one person did for another.', 'Use it to help a child notice help given and received at home, with the parent modeling specific thanks.', array['Children']::text[], 'Five minutes a day for two weeks', 'A strip of paper, a marker and tape make a link; the rule is one link a day, written by anyone in the house, naming something a family member did for someone else (Dad made my lunch, my sister waited for me). The chain grows across the kitchen doorway. The parent writes the first link and reads theirs aloud each evening so the child hears thanks that is specific rather than general. At the end of two weeks the family reads the whole chain. Watch for the child who writes only thanks to themselves; model a link about them first.', '[{"id": "f0", "type": "textarea", "label": "The link I added today, and who it was about:"}, {"id": "f1", "type": "textarea", "label": "A link someone wrote about me, and how it felt to read it:"}, {"id": "f2", "type": "textarea", "label": "The link my grown-up read aloud tonight:"}, {"id": "f3", "type": "textarea", "label": "How long the chain is now:"}, {"id": "f4", "type": "textarea", "label": "Something I noticed someone do today that could be tomorrow''s link:"}, {"id": "f5", "type": "textarea", "label": "Where the chain hangs in our house:"}]'::jsonb, array['parenting', 'children', 'gratitude']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('first-outing-with-the-baby-bag-exit-and-bail-plan-sheet', 'First Outing With the Baby Bag Exit and Bail Plan Sheet', 'worksheet'::resource_kind, 'A planning sheet for the new parent''s first trip out with the baby, with what to pack, where to stop, and when leaving is fine.', 'Use it to make the first outing small enough to succeed and to decide in advance that turning back is a success too.', array['Adults']::text[], '15 minutes the night before', 'The first outing with a newborn is a logistics problem the anxious mind turns into a test. The sheet makes it small: a destination under twenty minutes away, the bag packed the night before from a short list, one place to stop and feed or change, a person to text when they get there, and a bail rule (if the baby or I am done, we go home and that counts). It also asks what the mind is predicting will go wrong and how fixable each thing is. Watch for the parent who plans a full day; the first outing is an hour, and the second can be two.', '[{"id": "f0", "type": "textarea", "label": "Where we are going, and why that place for the first time:"}, {"id": "f1", "type": "textarea", "label": "The bag, packed from a short list the night before:"}, {"id": "f2", "type": "textarea", "label": "The one place I can stop to feed or change if needed:"}, {"id": "f3", "type": "textarea", "label": "Who I will text when we arrive:"}, {"id": "f4", "type": "textarea", "label": "My bail rule, and why turning back counts as success:"}, {"id": "f5", "type": "textarea", "label": "What my mind predicts will go wrong, and how fixable each one is:"}]'::jsonb, array['perinatal and postpartum', 'planning', 'confidence']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('everyone-elses-baby-sleeps-through-the-night-sheet', 'Everyone Else''s Baby Sleeps Through the Night Sheet', 'cbt'::resource_kind, 'A comparison sheet for the new parent convinced by the group chat and the pediatrician''s waiting room that every other baby sleeps.', 'Use it to examine where the comparison comes from and what is actually known about other families'' nights.', array['Adults']::text[], '15 minutes', 'Sleep comparison is where new parents'' self-criticism goes to feed. The sheet asks for the comparison thought, where it came from (a post, an offhand remark, a baby who looked rested), what the client actually knows about that family''s nights, what they leave out when they describe their own, and what they would think of a friend who said this about themselves. Then a fairer sentence about their own baby''s sleep. Keep sleep advice out of it; this is about the comparison, not the schedule. Watch for the parent who wants data on normal sleep; send that question to the pediatrician.', '[{"id": "f0", "type": "textarea", "label": "The comparison thought, and where it came from today:"}, {"id": "f1", "type": "textarea", "label": "What I actually know about that family''s nights, and what I am guessing:"}, {"id": "f2", "type": "textarea", "label": "What I leave out when I describe our nights to others:"}, {"id": "f3", "type": "textarea", "label": "What I would say to a friend who told me their baby was the only one awake:"}, {"id": "f4", "type": "textarea", "label": "A fairer sentence about our nights:"}, {"id": "f5", "type": "textarea", "label": "Who I could ask an honest question about their baby''s sleep this week:"}]'::jsonb, array['perinatal and postpartum', 'comparison', 'self-criticism']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('new-parent-mind-as-a-baby-monitor-stuck-on-full-volume-page', 'New Parent Mind as a Baby Monitor Stuck on Full Volume Page', 'act'::resource_kind, 'An ACT page that pictures the new parent''s mind as a monitor turned all the way up, amplifying every rustle into an alarm.', 'Use it to help a parent notice the volume setting as separate from the baby and let some rustles be rustles.', array['Adults']::text[], '10 minutes', 'A baby monitor on full volume makes every sigh a crisis, and a new parent''s mind runs the same way for months. The page asks the client to list the rustles their mind amplified today, what the amplified version said, what the quiet version would have said, and what their body did at each alarm. Then they practice noticing the volume as a setting: this is the monitor, not the baby. The page is not about ignoring real cries. Watch for the parent who hears the metaphor as being told they are overreacting; the volume is a nervous system doing its job too well.', '[{"id": "f0", "type": "textarea", "label": "Three rustles my mind turned into alarms today:"}, {"id": "f1", "type": "textarea", "label": "What the full-volume version of each said:"}, {"id": "f2", "type": "textarea", "label": "What the quiet version would have said:"}, {"id": "f3", "type": "textarea", "label": "What my body did at each alarm, and what it cost me by evening:"}, {"id": "f4", "type": "textarea", "label": "My sentence for noticing the setting (this is the monitor, not the baby):"}, {"id": "f5", "type": "textarea", "label": "One rustle I let be a rustle, and what happened:"}]'::jsonb, array['perinatal and postpartum', 'defusion', 'metaphor']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('observe-and-describe-the-spike-at-the-3-a-m-cry-card', 'Observe and Describe the Spike at the 3 a.m. Cry Card', 'dbt'::resource_kind, 'A DBT observe and describe card for the surge of frustration that rises when the baby cries at 3 a.m. for the third time.', 'Use it to put words to the spike before it turns into words at the baby, and to decide the next small step.', array['Adults']::text[], 'Two minutes in the night, then a morning review', 'The 3 a.m. spike is fast, hot and frightening to the parent who feels it. The card asks the client to observe it as it rises (the heat in the face, the clench, the thought), describe it in plain words without judging (frustration, 8 out of 10, in the jaw), and name the next step that is safe for both (put the baby down safely, step into the hall for sixty seconds, breathe, return). In the morning they review what the spike was and whether anything in the day fed it. Make clear the hall is allowed. Watch for the parent too ashamed to log the spike; shame goes in the description column too.', '[{"id": "f0", "type": "textarea", "label": "What I observed as the spike rose: body, thought, urge:"}, {"id": "f1", "type": "textarea", "label": "The description in plain words, with a number out of 10:"}, {"id": "f2", "type": "textarea", "label": "The safe next step I took, and how long it took the spike to drop:"}, {"id": "f3", "type": "textarea", "label": "What I said to myself in the hall:"}, {"id": "f4", "type": "textarea", "label": "In the morning: what in the day before fed the spike (sleep, food, no break)?"}, {"id": "f5", "type": "textarea", "label": "Who I could ask for one covered night this week:"}]'::jsonb, array['perinatal and postpartum', 'emotion regulation', 'mindfulness']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('visitors-after-the-birth-door-policy-for-new-parents', 'Visitors After the Birth Door Policy for New Parents', 'couples'::resource_kind, 'A new-parent agreement on who visits in the first weeks, for how long, and who delivers the no when it is needed.', 'Use it to put the couple on one side of the door before the relatives start arriving.', array['Couples']::text[], '20 minutes before the birth or in the first week', 'The first weeks bring love in the form of people who want to hold the baby and stay for dinner. The policy asks each partner who they want to see and when, who exhausts them, the visit length that works, what visitors should do while there (bring food, hold the baby while a parent sleeps), and the hard part: who tells which relative no or not yet, in what words. The couple writes the words together. Watch for the policy where one partner''s family gets rules and the other''s gets exceptions; the door is the same for both sides.', '[{"id": "f0", "type": "textarea", "label": "Partner A: who I want to see in the first two weeks, and who can wait:"}, {"id": "f1", "type": "textarea", "label": "Partner B: who I want to see in the first two weeks, and who can wait:"}, {"id": "f2", "type": "textarea", "label": "Our visit length, and what visitors do while they are here:"}, {"id": "f3", "type": "textarea", "label": "Who tells which relative not yet, and the words we will use:"}, {"id": "f4", "type": "textarea", "label": "How we signal each other that a visit needs to end:"}, {"id": "f5", "type": "textarea", "label": "When we revisit the policy, and what would tell us it is working:"}]'::jsonb, array['perinatal and postpartum', 'couples', 'boundaries']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('rest-without-earning-it-day-off-log-sheet', 'Rest Without Earning It Day Off Log Sheet', 'worksheet'::resource_kind, 'A log for the client who cannot rest without first having done enough to deserve it, and so never does.', 'Use it to take one day off with nothing earned first, and record what the rest and the guilt actually did.', array['Adults', 'Teens']::text[], 'One day, then 15 minutes', 'For a client whose worth is a ledger, rest has to be paid for first, and the bill is never settled. The log asks for the rule (I can rest when), what rest the client took last month and what they did to earn it, and then one planned day or half day of rest with nothing earned beforehand. During the day they log the guilt out of 10 every two hours, what they did, and what the guilt said. At the end, whether anything the guilt predicted happened. Watch for the client who does chores before the day off to earn it in advance; the point is the unearned part.', '[{"id": "f0", "type": "textarea", "label": "My rule for when rest is allowed, in my words:"}, {"id": "f1", "type": "textarea", "label": "Rest I took last month, and what I did first to earn it:"}, {"id": "f2", "type": "textarea", "label": "My unearned rest day: when, and what I will do with it:"}, {"id": "f3", "type": "textarea", "label": "Guilt out of 10 every two hours, and what it said each time:"}, {"id": "f4", "type": "textarea", "label": "What the guilt predicted would happen, and what did:"}, {"id": "f5", "type": "textarea", "label": "What I want to believe about rest after this, and how much I do:"}]'::jsonb, array['self-esteem', 'self-care', 'worth']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('if-i-ask-a-question-i-will-look-stupid-belief-sheet', 'If I Ask a Question I Will Look Stupid Belief Sheet', 'cbt'::resource_kind, 'A belief sheet for the client who sits through meetings and classes confused rather than ask the question everyone else is wondering.', 'Use it to test the belief against how the client sees others who ask, and run one asked question as an experiment.', array['Adults', 'Teens']::text[], '20 minutes, then one week', 'The client who never asks has a belief about what asking costs, and has never collected the data. The sheet asks for the belief and its confidence, what they think when someone else asks a question in a meeting, the last time someone asked something the client was also wondering, what not asking has cost them (the task done wrong, the hour lost), and an experiment: one question asked this week, with a prediction and an outcome. Watch for the client who asks the question in a self-mocking preface (this is probably stupid but); the experiment is the question without the preface.', '[{"id": "f0", "type": "textarea", "label": "The belief, and how much I believe it today:"}, {"id": "f1", "type": "textarea", "label": "What I actually think when someone else asks a question:"}, {"id": "f2", "type": "textarea", "label": "The last time someone asked what I was also wondering, and what happened to them:"}, {"id": "f3", "type": "textarea", "label": "What not asking has cost me this month:"}, {"id": "f4", "type": "textarea", "label": "My question this week, said without a self-mocking preface, and my prediction:"}, {"id": "f5", "type": "textarea", "label": "What happened, and how much I believe the belief now:"}]'::jsonb, array['self-esteem', 'core beliefs', 'behavioral experiment']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('mind-as-a-heckler-in-the-cheap-seats-page', 'Mind as a Heckler in the Cheap Seats Page', 'act'::resource_kind, 'An ACT defusion page that casts the inner critic as a heckler shouting from the back row while the client is on stage living.', 'Use it to help a client keep performing their life while the heckler keeps up its commentary from the dark.', array['Adults', 'Teens']::text[], '10 minutes', 'A heckler is loud, anonymous, and has never once been on the stage. The page asks the client to write down the heckler''s three favorite lines, notice where in the house it sits (the back row, the dark), what happens to the show when the performer stops to argue with it, and what a performer who keeps going does with the shout. Then they practice a show (a task, a conversation) with the heckler allowed to shout. The tone is wry, not combative. Watch for the client who wants to throw the heckler out; the exercise is finishing the show with it there.', '[{"id": "f0", "type": "textarea", "label": "The heckler''s three favorite lines about me:"}, {"id": "f1", "type": "textarea", "label": "Where it sits, and what it has ever actually done on a stage:"}, {"id": "f2", "type": "textarea", "label": "What happens to my show when I stop to argue with it:"}, {"id": "f3", "type": "textarea", "label": "What a performer who keeps going does with the shout:"}, {"id": "f4", "type": "textarea", "label": "The show I will finish this week with the heckler shouting:"}, {"id": "f5", "type": "textarea", "label": "What I noticed about the heckling when I stopped turning around:"}]'::jsonb, array['self-esteem', 'defusion', 'self-criticism']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('cheerleading-statements-for-the-family-dinner-quiz-card', 'Cheerleading Statements for the Family Dinner Quiz Card', 'dbt'::resource_kind, 'A DBT cheerleading statements card for the relative who asks about the client''s job, love life and plans in a tone that lands as a grade.', 'Use it to arm a client with three true, kind statements to repeat silently between the questions.', array['Adults', 'Teens']::text[], '10 minutes to write, one dinner to use', 'Some relatives ask questions that are really report cards, and the client leaves the table failing. Cheerleading statements are the DBT answer: short, true, encouraging lines the client says to themselves (I am allowed to be where I am; I do not owe anyone a five-year plan). The card asks for the questions expected, the statements written in the client''s words, where they will keep them (a phone note, a palm), and a short answer plus a subject change for each question. Watch for statements that are arguments with the relative; they are for the client, not the fight.', '[{"id": "f0", "type": "textarea", "label": "The questions I expect, and the tone they usually come in:"}, {"id": "f1", "type": "textarea", "label": "My three cheerleading statements, true and in my own words:"}, {"id": "f2", "type": "textarea", "label": "Where I will keep them during dinner:"}, {"id": "f3", "type": "textarea", "label": "A short answer and a subject change for each question:"}, {"id": "f4", "type": "textarea", "label": "How I used the statements at the table, and what they did:"}, {"id": "f5", "type": "textarea", "label": "The statement I will keep for other rooms:"}]'::jsonb, array['self-esteem', 'cheerleading statements', 'family']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('say-it-without-shrinking-brag-bingo-game', 'Say It Without Shrinking Brag Bingo Game', 'game'::resource_kind, 'A bingo game in which players fill squares by stating real accomplishments aloud, at full volume, with no qualifier attached.', 'Use it to practice taking credit in front of others in a group where the only penalty is for shrinking.', array['Groups', 'Teens']::text[], '20 minutes', 'Rules: each player gets a bingo card with categories (something I made, something I fixed, something kind I did, something I finished, something I learned). Around the circle, a player states one true accomplishment for a square, at full volume, with no qualifier (no just, no only, no it was nothing). The group calls shrink if a qualifier sneaks in and the square stays empty until it is restated clean. First to a line wins. Debrief: which qualifiers were hardest to drop, and how the body felt saying it clean. Make the shrink call a cheer, never a jeer.', '[{"id": "f0", "type": "textarea", "label": "The accomplishments I claimed, square by square:"}, {"id": "f1", "type": "textarea", "label": "The qualifier I kept trying to add:"}, {"id": "f2", "type": "textarea", "label": "How my body felt saying one clean, with no shrink:"}, {"id": "f3", "type": "textarea", "label": "What the group''s faces actually did when I claimed something:"}, {"id": "f4", "type": "textarea", "label": "Someone else''s claim I admired:"}, {"id": "f5", "type": "textarea", "label": "One thing I will claim clean outside the group this week:"}]'::jsonb, array['self-esteem', 'game', 'strengths']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('video-call-with-distant-relatives-opening-lines-sheet', 'Video Call With Distant Relatives Opening Lines Sheet', 'worksheet'::resource_kind, 'A script sheet for the holiday video call with relatives the client sees once a year and does not know what to say to.', 'Use it to prepare three openers, three questions and an exit line, so the call is a plan rather than a stare at the screen.', array['Adults', 'Teens']::text[], '15 minutes before the call', 'The group video call is a social situation with a spotlight (the tile lights up when you speak) and no small talk to hide in. The sheet asks for who will be on the call, three openers that are not how are you, three questions the client can ask any relative, one thing about their own year they are willing to share, where their eyes will go when they are not talking, and an exit line for when they have had enough. Rehearse the openers aloud. Watch for the client who plans to keep the camera off; the camera on with a plan is the practice.', '[{"id": "f0", "type": "textarea", "label": "Who will be on the call, and who I find easiest:"}, {"id": "f1", "type": "textarea", "label": "My three openers that are not how are you:"}, {"id": "f2", "type": "textarea", "label": "Three questions I can ask anyone on the call:"}, {"id": "f3", "type": "textarea", "label": "One thing about my year I am willing to share, in two sentences:"}, {"id": "f4", "type": "textarea", "label": "Where my eyes will go when I am not talking:"}, {"id": "f5", "type": "textarea", "label": "My exit line, and how long I plan to stay:"}]'::jsonb, array['social anxiety', 'social skills', 'family']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('a-pause-in-the-conversation-means-i-failed-thought-record', 'A Pause in the Conversation Means I Failed Thought Record', 'cbt'::resource_kind, 'A thought record for the client who hears every silence in a conversation as proof they have run out of things to say and been found out.', 'Use it to test what a pause means, against how the client reads pauses when others leave them.', array['Adults', 'Teens']::text[], '20 minutes', 'A two-second pause feels like a minute to the client who is monitoring the conversation for failure. The record takes a recent pause, the hot thought (they are bored, I have nothing), the emotion, the evidence for and against, what the client assumes when someone else lets a pause fall, and what happened after the pause (the conversation went on, nobody left). A balanced thought often reads: pauses are how conversations breathe. Then one practice: letting a pause sit for three seconds on purpose. Watch for the client who fills the pause with an apology; the record covers that too.', '[{"id": "f0", "type": "textarea", "label": "The conversation and the pause, as I remember it:"}, {"id": "f1", "type": "textarea", "label": "The hot thought, and how strong the feeling was, out of 10:"}, {"id": "f2", "type": "textarea", "label": "Evidence that the pause meant I failed:"}, {"id": "f3", "type": "textarea", "label": "Evidence against it, including what happened right after the pause:"}, {"id": "f4", "type": "textarea", "label": "What I assume when someone else lets a pause fall:"}, {"id": "f5", "type": "textarea", "label": "A balanced thought, and one pause I will let sit for three seconds this week:"}]'::jsonb, array['social anxiety', 'thought record', 'conversation']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('carrying-the-trembling-hands-into-the-toast-page', 'Carrying the Trembling Hands Into the Toast Page', 'act'::resource_kind, 'An ACT willingness page for the client asked to raise a glass and say a few words while their hands shake visibly.', 'Use it to practice making the toast with the tremor present, as the price of being the person who speaks for the table.', array['Adults', 'Teens']::text[], '15 minutes, then one toast', 'A visible tremor and a raised glass is the social anxiety nightmare in miniature. The page asks the client what the toast is for (who they are honoring, what they want them to hear), what the mind says the tremor will cost, what refusing the toast would cost, and what it would mean to carry the shaking hand up with the glass anyway. They write the toast short, three sentences, and practice it in session with a glass of water and a willing hand. Watch for the client who plans to hold the glass with both hands to hide it; one hand, and the shake is allowed.', '[{"id": "f0", "type": "textarea", "label": "Who the toast is for, and the one thing I want them to hear:"}, {"id": "f1", "type": "textarea", "label": "What my mind says the tremor will cost me:"}, {"id": "f2", "type": "textarea", "label": "What refusing to speak would cost me and them:"}, {"id": "f3", "type": "textarea", "label": "My three-sentence toast:"}, {"id": "f4", "type": "textarea", "label": "What carrying the shaking hand up with the glass would mean about who I am:"}, {"id": "f5", "type": "textarea", "label": "How the toast went, and what the hand did halfway through:"}]'::jsonb, array['social anxiety', 'willingness', 'values']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('give-skills-at-the-neighbors-open-house-card', 'GIVE Skills at the Neighbor''s Open House Card', 'dbt'::resource_kind, 'A DBT GIVE card for the neighborhood open house where the client knows no one and has to make conversation for an hour.', 'Use it to give a client four concrete things to do with their face, voice and attention when the small talk starts.', array['Adults', 'Teens']::text[], 'One event', 'Open house small talk has no agenda, which makes it hard. GIVE gives the client a job: Gentle (no sarcasm, no eye rolls at the gossip), Interested (ask about the house, the street, how long they have lived here, and listen to the whole answer), Validate (that sounds like a project), Easy manner (a half smile, a light tone). The card asks the client to pick one neighbor to practice all four with, note what they learned about that person, and rate how the hour went compared with their prediction. Watch for the client who does Interested as an interview; two questions, then share something.', '[{"id": "f0", "type": "textarea", "label": "My prediction for the hour, out of 10:"}, {"id": "f1", "type": "textarea", "label": "The neighbor I chose to practice GIVE with:"}, {"id": "f2", "type": "textarea", "label": "Gentle and Easy manner: what my face and voice were doing:"}, {"id": "f3", "type": "textarea", "label": "Interested: two questions I asked, and what I learned:"}, {"id": "f4", "type": "textarea", "label": "Validate: the one sentence I used:"}, {"id": "f5", "type": "textarea", "label": "How the hour actually went, out of 10, and what I would do again:"}]'::jsonb, array['social anxiety', 'GIVE', 'interpersonal effectiveness']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('hold-the-silence-three-second-stare-down-game', 'Hold the Silence Three Second Stare Down Game', 'game'::resource_kind, 'A partner game in which pairs let a conversational silence sit for three full seconds before anyone speaks, and build up to ten.', 'Use it to make silence in conversation familiar and even funny, so a pause stops feeling like a failure.', array['Groups', 'Teens']::text[], '15 minutes', 'Rules: pairs sit facing each other. One asks an ordinary question (what did you have for breakfast). The other must wait three full seconds, counted silently, before answering, keeping eye contact and a relaxed face. Then swap. Each round adds two seconds, up to ten. Anyone who fills the silence with a noise or a word loses the round, and the pair starts the count again. Debrief with the group: what the silence felt like at three, at seven, at ten; what the body wanted to do; and whether the partner looked bored or just waiting. Giggling is allowed; speaking is not.', '[{"id": "f0", "type": "textarea", "label": "What the three-second silence felt like the first time:"}, {"id": "f1", "type": "textarea", "label": "What my body wanted to do during the ten-second one:"}, {"id": "f2", "type": "textarea", "label": "What my partner''s face looked like while they waited, honestly:"}, {"id": "f3", "type": "textarea", "label": "Whether the silence changed the answer I gave:"}, {"id": "f4", "type": "textarea", "label": "A real conversation this week where I will let a pause sit:"}, {"id": "f5", "type": "textarea", "label": "The number of seconds I think I could manage there:"}]'::jsonb, array['social anxiety', 'game', 'conversation']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('holiday-cards-signed-without-their-name-decision-sheet', 'Holiday Cards Signed Without Their Name Decision Sheet', 'worksheet'::resource_kind, 'A decision sheet for the first season of holiday cards after a death, when the signature has one name fewer.', 'Use it to decide whether to send cards at all, how to sign them, and what to do with the ones addressed to both of you.', array['Adults']::text[], '20 minutes', 'The card list is a small task that becomes enormous: whose name goes where, who has not heard, what to do with the cards that arrive addressed to two people. The sheet asks whether cards go out this year at all (skipping is allowed), how the client wants to sign (their name alone, their name and in memory of, a line about the loss), who on the list does not yet know and how they will be told, and what happens to incoming cards with both names. One decision at a time. Watch for the client who decides to do all of it exactly as before to prove they can; ask what they want.', '[{"id": "f0", "type": "textarea", "label": "Whether cards go out this year, and what I would feel either way:"}, {"id": "f1", "type": "textarea", "label": "How I want to sign, and how that reads when I say it aloud:"}, {"id": "f2", "type": "textarea", "label": "Who on my list does not know yet, and how I want them to find out:"}, {"id": "f3", "type": "textarea", "label": "What I will do with cards that arrive addressed to both of us:"}, {"id": "f4", "type": "textarea", "label": "The one person I would like to write a longer note to this year:"}, {"id": "f5", "type": "textarea", "label": "What I will do after the cards are done, so the task has a soft landing:"}]'::jsonb, array['grief and loss', 'decisions', 'holidays']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('if-i-stop-crying-i-am-letting-them-go-check-sheet', 'If I Stop Crying I Am Letting Them Go Check Sheet', 'cbt'::resource_kind, 'A thought check sheet for the client who fears that a day without tears means the person is slipping away from them.', 'Use it to examine the link between crying and love, so a steadier day can be allowed without guilt.', array['Adults', 'Teens']::text[], '20 minutes', 'Early grief measures love in tears, and the first dry day frightens the client. The sheet asks for the thought, how much they believe it, what they think love and connection are made of beyond crying (talking about them, their recipes, their photo on the shelf, the habits they left behind), what the person themselves would have said about the client''s tears, and what a dry day actually held of them. A revised thought often reads: the crying is one way I carry them, not the only way. Watch for the client who starts crying on purpose to be safe; name it gently.', '[{"id": "f0", "type": "textarea", "label": "The thought, in my words, and how much I believe it:"}, {"id": "f1", "type": "textarea", "label": "Everything besides crying that connects me to them, in a list:"}, {"id": "f2", "type": "textarea", "label": "What a dry day this week actually held of them:"}, {"id": "f3", "type": "textarea", "label": "What they would have said about my tears, in their voice:"}, {"id": "f4", "type": "textarea", "label": "A revised thought about crying and carrying them:"}, {"id": "f5", "type": "textarea", "label": "How much I believe the old thought now, out of 10:"}]'::jsonb, array['grief and loss', 'core beliefs', 'guilt']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('grief-as-the-tide-line-left-on-the-sand-page', 'Grief as the Tide Line Left on the Sand Page', 'act'::resource_kind, 'An ACT page that pictures grief as the line the tide leaves: the water pulls back, and the mark of how far it came stays.', 'Use it to help a client make room for grief that recedes and returns, and to notice what each tide leaves behind.', array['Adults', 'Teens']::text[], '15 minutes', 'Grief comes in and goes out, and the client often panics at both: the wave means they are drowning and the retreat means they are forgetting. The page offers the tide line, the mark on the sand that shows how far the water came. The client describes this week''s high tide (where it reached, what it carried in), the pull back, and what was left on the sand (a memory, a smell, a thing they want to do in the person''s name). The page is not about calming the sea. Watch for the client who wants the water never to come back; tide lines need the tide.', '[{"id": "f0", "type": "textarea", "label": "This week''s high tide: where it reached, and what it carried in:"}, {"id": "f1", "type": "textarea", "label": "What the pull back felt like, and what I feared it meant:"}, {"id": "f2", "type": "textarea", "label": "What the tide left on the sand this time (a memory, a thing to do, a word):"}, {"id": "f3", "type": "textarea", "label": "How the tide line has changed since the early weeks:"}, {"id": "f4", "type": "textarea", "label": "One thing I will do with what this tide left:"}, {"id": "f5", "type": "textarea", "label": "What I want to remember about the sea when the next tide comes:"}]'::jsonb, array['grief and loss', 'metaphor', 'acceptance']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('self-soothe-with-their-sweater-around-my-shoulders-card', 'Self-Soothe With Their Sweater Around My Shoulders Card', 'dbt'::resource_kind, 'A DBT self-soothe card built on wearing the lost person''s sweater for ten minutes on a hard evening.', 'Use it to give a client a deliberate, time-limited comfort that uses what they already have in the closet.', array['Adults', 'Teens']::text[], 'Ten minutes on a hard evening', 'The sweater in the closet is either avoided or clutched for hours, and the card offers a middle: a chosen ten minutes with it around the shoulders, attending to the weight, the smell that remains, the texture at the collar, the warmth building, a sound in the room. Then it goes back on the hook, and the client does one small next thing. The timer makes it a skill rather than a slide. Watch for the client who cannot put it back; make the ten minutes twenty, and keep the hook.', '[{"id": "f0", "type": "textarea", "label": "The sweater, and where it has lived since:"}, {"id": "f1", "type": "textarea", "label": "The weight of it on my shoulders, and the smell that remains:"}, {"id": "f2", "type": "textarea", "label": "The texture at the collar, and one sound in the room while I wore it:"}, {"id": "f3", "type": "textarea", "label": "What came up in the ten minutes, in a few words:"}, {"id": "f4", "type": "textarea", "label": "What I did when the timer went and it was back on the hook:"}, {"id": "f5", "type": "textarea", "label": "How the rest of the evening went compared with evenings I avoided or held on:"}]'::jsonb, array['grief and loss', 'self-soothing', 'distress tolerance']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('their-favorite-color-paper-chain-memory-craft', 'Their Favorite Color Paper Chain Memory Craft', 'kids'::resource_kind, 'A craft in which a child makes a paper chain in the lost person''s favorite color, with one memory or question written on each link.', 'Use it to give a grieving child a way to hold memories and ask questions a little at a time, with the parent adding links too.', array['Children']::text[], '20 minutes to start, then a link whenever', 'Children grieve in pieces, and a chain is grief in pieces made visible. Strips of paper in the person''s favorite color sit in a box with a marker; whenever the child remembers something or has a question (where are they now, did they like the snow), they write or draw it on a strip and add a link. The parent adds links of their own memories and answers questions on new links, honestly and simply. The chain hangs where the child chooses. Watch for the parent who answers only the easy questions; the hard ones get a link too, in words a child can hold.', '[{"id": "f0", "type": "textarea", "label": "The color I chose, and why it was their favorite:"}, {"id": "f1", "type": "textarea", "label": "A memory I put on a link today:"}, {"id": "f2", "type": "textarea", "label": "A question I put on a link, and what my grown-up wrote back:"}, {"id": "f3", "type": "textarea", "label": "A link my grown-up added about them:"}, {"id": "f4", "type": "textarea", "label": "Where my chain hangs:"}, {"id": "f5", "type": "textarea", "label": "How many links we have now, and one I want to add tomorrow:"}]'::jsonb, array['grief and loss', 'children', 'craft']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('my-partners-friend-i-cannot-stand-plan-sheet', 'My Partner''s Friend I Cannot Stand Plan Sheet', 'worksheet'::resource_kind, 'A plan sheet for the client who has to spend an evening with a partner''s friend they dislike, without making it the partner''s problem.', 'Use it to separate what the friend does from what it means, set a civil floor for the evening, and decide what to say to the partner.', array['Adults']::text[], '20 minutes before the evening', 'Disliking a partner''s friend is normal; turning every gathering into a loyalty test is corrosive. The sheet asks what specifically the friend does that grates, what the client has decided it means about the friend and about the partner, a civil floor for the evening (polite, one real question, no eye rolls), how long they will stay, and what, if anything, they want to say to their partner afterward that is a request rather than a verdict. Watch for the client who plans to be civil and then debriefs the partner for an hour; the request is one sentence.', '[{"id": "f0", "type": "textarea", "label": "What this friend does that grates on me, specifically:"}, {"id": "f1", "type": "textarea", "label": "What I have decided it means about them, and about my partner for liking them:"}, {"id": "f2", "type": "textarea", "label": "My civil floor for the evening (what I will do, and what I will not):"}, {"id": "f3", "type": "textarea", "label": "How long I will stay, and my exit line:"}, {"id": "f4", "type": "textarea", "label": "What I want to say to my partner afterward, as one request rather than a verdict:"}, {"id": "f5", "type": "textarea", "label": "How the evening went compared with my prediction:"}]'::jsonb, array['relationship issues', 'boundaries', 'planning']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('they-did-not-defend-me-at-dinner-thought-record', 'They Did Not Defend Me at Dinner Thought Record', 'cbt'::resource_kind, 'A thought record for the client whose partner or friend stayed quiet when a relative took a dig at them across the table.', 'Use it to test what the silence meant before it becomes the verdict of the whole relationship.', array['Adults', 'Teens']::text[], '20 minutes', 'A dig across the table and a silence beside you can feel like betrayal, and the drive home decides the case before the other person has been asked. The record takes the moment, the hot thought (they do not have my back), the feeling, the evidence for it, and the evidence against (how they handled it after, what they have done other times, what they might have been weighing in the moment), then a balanced thought and the question the client could ask them directly. Watch for the client who skips the asking; the record ends with the question, not the verdict.', '[{"id": "f0", "type": "textarea", "label": "What was said at the table, and what my person did or did not do:"}, {"id": "f1", "type": "textarea", "label": "The hot thought, and how strong the feeling was, out of 10:"}, {"id": "f2", "type": "textarea", "label": "Evidence that their silence meant they do not have my back:"}, {"id": "f3", "type": "textarea", "label": "Evidence against it, including what they did afterward and other times:"}, {"id": "f4", "type": "textarea", "label": "A balanced thought I can hold until I have asked them:"}, {"id": "f5", "type": "textarea", "label": "The question I will ask them, in the words I will use:"}]'::jsonb, array['relationship issues', 'thought record', 'family']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('scorekeeping-as-a-game-nobody-has-ever-won-page', 'Scorekeeping as a Game Nobody Has Ever Won Page', 'act'::resource_kind, 'An ACT page for the client who keeps a running tally of who did more, called more and gave more in a relationship.', 'Use it to look at what the scoreboard costs and what the client would be doing if they put down the pencil.', array['Adults', 'Teens']::text[], '15 minutes', 'A scoreboard in a relationship feels like fairness and works like a slow leak. The page asks the client to write the current score as they keep it, what keeping it costs (the attention, the warmth, the way every gift is weighed), whether anyone has ever ended a game of this by winning, and what they would do with the energy if the scoreboard went dark for a week. It does not ask them to accept unfairness; a real imbalance gets a conversation, which the page names. Watch for the client who stops keeping score and starts keeping score of how well they stopped.', '[{"id": "f0", "type": "textarea", "label": "The current score, as I keep it:"}, {"id": "f1", "type": "textarea", "label": "What keeping the score costs me each week:"}, {"id": "f2", "type": "textarea", "label": "Whether this game has ever been won, by me or anyone I know:"}, {"id": "f3", "type": "textarea", "label": "What I would do with the attention if the scoreboard went dark for a week:"}, {"id": "f4", "type": "textarea", "label": "Whether there is a real imbalance under the score that needs a conversation, and its first line:"}, {"id": "f5", "type": "textarea", "label": "What I noticed in the week without the pencil:"}]'::jsonb, array['relationship issues', 'workability', 'fairness']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('dear-man-for-sharing-one-car-with-a-roommate-card', 'DEAR MAN for Sharing One Car With a Roommate Card', 'dbt'::resource_kind, 'A DEAR MAN card for the client whose shared-car arrangement has drifted into one person always driving and never being asked.', 'Use it to script a specific, respectful request to renegotiate the car, and to hold the line if the roommate deflects.', array['Adults', 'Teens']::text[], '20 minutes to script, one conversation', 'Shared cars run on unspoken rules until one person is resentful and the other is surprised. The card walks through Describe (the last month''s use, as fact), Express (how it has landed), Assert (the specific proposal: a shared calendar, a gas split, a weekend rotation), Reinforce (what the roommate gets), and the MAN half: staying on topic, sounding like someone who expects a fair answer, and naming what they would accept short of the full ask. Rehearse the deflection the roommate is likely to use. Watch for the client whose Describe includes the word always; swap it for a number.', '[{"id": "f0", "type": "textarea", "label": "Describe: the facts of the car this month, with numbers instead of always:"}, {"id": "f1", "type": "textarea", "label": "Express: how it has landed for me, in one sentence:"}, {"id": "f2", "type": "textarea", "label": "Assert: my specific proposal:"}, {"id": "f3", "type": "textarea", "label": "Reinforce: what my roommate gets out of agreeing:"}, {"id": "f4", "type": "textarea", "label": "Mindful: the deflection I expect, and the line I will return to:"}, {"id": "f5", "type": "textarea", "label": "Negotiate: what I could accept that is not my first ask:"}]'::jsonb, array['relationship issues', 'DEAR MAN', 'fairness']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('different-tidiness-standards-truce-for-partners', 'Different Tidiness Standards Truce for Partners', 'couples'::resource_kind, 'A couples truce for the partner who needs clear counters and the partner who does not see the mess, before the next silent clean-up.', 'Use it to name each partner''s threshold, agree on shared zones and private ones, and retire the sighing.', array['Couples']::text[], 'One session', 'Tidiness fights are rarely about the counter; they are about feeling unseen (I clean and nobody notices) and feeling judged (I am being treated like a child). The truce asks each partner what mess does to them, where their own threshold is, which rooms are shared standard and which are each partner''s own, who does what in the shared zones and by when, and what each will stop doing (the sigh, the pile moved onto the other''s desk). Both partners give up something. Watch for the truce that lists the messier partner''s jobs only; the tidier partner''s part is the sighing and the standard.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what mess does to me, and where my threshold is:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what being tidied around does to me, and where my threshold is:"}, {"id": "f2", "type": "textarea", "label": "Our shared-standard rooms, and the rooms that are each partner''s own:"}, {"id": "f3", "type": "textarea", "label": "Who does what in the shared rooms, and by when each week:"}, {"id": "f4", "type": "textarea", "label": "Partner A: what I will stop doing (the sigh, the silent clean-up, the comment):"}, {"id": "f5", "type": "textarea", "label": "Partner B: what I will stop doing (the pile, the promise for tomorrow):"}]'::jsonb, array['relationship issues', 'couples', 'fairness']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('being-asked-why-i-avoid-certain-relatives-reply-sheet', 'Being Asked Why I Avoid Certain Relatives Reply Sheet', 'worksheet'::resource_kind, 'A reply sheet for the client who is pressed at gatherings about why they keep their distance from a particular family member.', 'Use it to prepare short replies that protect the client''s privacy and their choice, with no disclosure required.', array['Adults', 'Teens']::text[], '15 minutes before a gathering', 'A client who keeps their distance from the person who hurt them is often asked to explain, by relatives who do not know and would not understand. The sheet prepares replies that disclose nothing (I keep my own company at these things; that is not something I am going to get into today), a change of subject, an ally who knows enough to run interference, and what the client will do if they are pushed. The client owes no one the story. Watch for the client who feels they must justify themselves; the reply is a boundary, not a defense, and it needs no reason attached.', '[{"id": "f0", "type": "textarea", "label": "Who is likely to ask, and how they usually put it:"}, {"id": "f1", "type": "textarea", "label": "My short reply that discloses nothing, in words I can say calmly:"}, {"id": "f2", "type": "textarea", "label": "The subject I will change to:"}, {"id": "f3", "type": "textarea", "label": "The person at the gathering who knows enough to help, and what I have asked of them:"}, {"id": "f4", "type": "textarea", "label": "What I will do if someone pushes past the reply:"}, {"id": "f5", "type": "textarea", "label": "How I will take care of myself in the hour after the gathering:"}]'::jsonb, array['sexual abuse', 'boundaries', 'safety']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('still-startling-means-i-will-never-heal-gentle-check-sheet', 'Still Startling Means I Will Never Heal Gentle Check Sheet', 'cbt'::resource_kind, 'A gentle thought check for the client who flinched at a sudden touch this week and took it as proof that nothing has changed.', 'Use it to look at one startle beside everything that has changed, without asking the client to revisit what happened.', array['Adults', 'Teens']::text[], '20 minutes, in session', 'A flinch is fast and the conclusion drawn from it is faster: I will always be like this. The sheet takes the startle as a single event, the thought it produced, and sets it beside the record of change the client can see (how long it took to settle this time compared with a year ago, who they told, what they did next). The nervous system''s startle is not the measure of healing; what happens in the minute after is. Keep the content of the past out of the sheet. Watch for the client who wants to list every startle this month as evidence; one event, and the minute after.', '[{"id": "f0", "type": "textarea", "label": "The startle this week, in one line, and the thought that followed:"}, {"id": "f1", "type": "textarea", "label": "How much I believed the thought in the moment, out of 10:"}, {"id": "f2", "type": "textarea", "label": "How long it took me to settle, compared with how long it took a year ago:"}, {"id": "f3", "type": "textarea", "label": "What I did in the minute after (told someone, grounded, kept going):"}, {"id": "f4", "type": "textarea", "label": "Three other things that have changed for me since the early days:"}, {"id": "f5", "type": "textarea", "label": "A gentler thought about the startle, and how much I believe it:"}]'::jsonb, array['sexual abuse', 'core beliefs', 'stabilizing']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('trust-as-a-dimmer-switch-not-a-toggle-page', 'Trust as a Dimmer Switch Not a Toggle Page', 'act'::resource_kind, 'An ACT page that pictures trust as a dimmer the client turns up a notch at a time, rather than a switch that is on or off.', 'Use it to help a client let a safe person a little closer without feeling they have handed over everything.', array['Adults', 'Teens']::text[], '15 minutes', 'After abuse, trust often becomes binary: a person is all the way in or all the way out, and all the way in feels impossible. The page offers a dimmer. The client picks one safe person, names where the dimmer sits with them now, out of 10, what one notch up would look like in a concrete act (telling them a small true thing, accepting a ride), what they would watch for before turning it up again, and that they hold the dial. Nothing here is about the past or about the person who hurt them. Watch for the client who turns the dimmer to full to get it over with; one notch, then watching.', '[{"id": "f0", "type": "textarea", "label": "The safe person I am thinking about, and where the dimmer sits with them now, out of 10:"}, {"id": "f1", "type": "textarea", "label": "What one notch up would look like, as a concrete act:"}, {"id": "f2", "type": "textarea", "label": "What I will watch for before I turn it up again:"}, {"id": "f3", "type": "textarea", "label": "What tells me it is all right to turn it down a notch, and that I am allowed to:"}, {"id": "f4", "type": "textarea", "label": "How the one notch went:"}, {"id": "f5", "type": "textarea", "label": "Who holds the dial:"}]'::jsonb, array['sexual abuse', 'values', 'trust']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('observe-the-weight-of-the-blanket-at-lights-out-card', 'Observe the Weight of the Blanket at Lights Out Card', 'dbt'::resource_kind, 'A DBT observe card for the moment the light goes off and the body braces, using the weight of the blanket as the anchor.', 'Use it to give a client something steady to attend to in the first minute of the dark, in a bed they have made safe.', array['Adults', 'Teens']::text[], 'Two minutes at bedtime', 'The dark is when the body remembers, and the first minute after the light goes off is the hardest. The card asks the client to notice the weight of the blanket across the legs, the chest and the shoulders, where it presses most, where the warmth gathers, and the sound of their own breath under it, returning to the weight each time attention leaves. The bed itself is arranged first (the door, the light within reach, a sound on). The card does not ask what the body remembers. Watch for the client who uses the blanket to hide; the point is weight they can feel, not cover.', '[{"id": "f0", "type": "textarea", "label": "How I have arranged the room so the bed feels safe enough (door, light, sound):"}, {"id": "f1", "type": "textarea", "label": "Where the blanket''s weight presses most when I lie down:"}, {"id": "f2", "type": "textarea", "label": "Where the warmth gathers first:"}, {"id": "f3", "type": "textarea", "label": "What my breath sounds like under it:"}, {"id": "f4", "type": "textarea", "label": "How many times I came back to the weight in the first minute:"}, {"id": "f5", "type": "textarea", "label": "What the second minute was like compared with nights without the card:"}]'::jsonb, array['sexual abuse', 'grounding', 'sleep']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('safe-circle-rope-ring-who-comes-in-play', 'Safe Circle Rope Ring Who Comes In Play', 'kids'::resource_kind, 'A play in which a child lays a rope ring on the floor as their safe circle and decides who may step in, with the parent asking first.', 'Use it to teach a child that their body has a space around it, that they decide who enters, and that grown-ups ask.', array['Children']::text[], '20 minutes', 'A jump rope or a length of yarn on the floor becomes the child''s circle. The parent, a sibling or a toy approaches and asks, may I come in, and the child says yes or no, and the answer is honored every time with no sulking. Then they swap, and the child asks to enter the parent''s circle. The talk afterward: your body has a circle around it everywhere, you decide who comes in, and safe grown-ups ask. If a child says something during the play that suggests someone has not asked, the clinician follows their reporting duties. The parent never steps in as a joke; the asking is the lesson.', '[{"id": "f0", "type": "textarea", "label": "What my circle looks like, and how big I made it:"}, {"id": "f1", "type": "textarea", "label": "Who I let in today, and who I said not right now to:"}, {"id": "f2", "type": "textarea", "label": "What my grown-up did when I said no:"}, {"id": "f3", "type": "textarea", "label": "How it felt to ask to come into someone else''s circle:"}, {"id": "f4", "type": "textarea", "label": "A grown-up who is safe and always asks:"}, {"id": "f5", "type": "textarea", "label": "What I would do if someone came into my circle without asking:"}]'::jsonb, array['sexual abuse', 'children', 'safety']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('coping-skill-of-the-week-trial-and-verdict-log-sheet', 'Coping Skill of the Week Trial and Verdict Log Sheet', 'worksheet'::resource_kind, 'A log in which the client trials one coping skill for a week, uses it at least three times, and gives it a verdict.', 'Use it to build a tested toolkit one skill at a time rather than a list of things the client has heard of.', array['Adults', 'Teens']::text[], 'One week per skill', 'Most clients have a list of coping skills and no idea which ones work for them. The log picks one skill a week, asks when it will be tried (at least three times, including once when it is not needed), what each use felt like out of 10 before and after, where it fit and where it did not, and a verdict: keep, adapt or drop. Over a month the client has four tested verdicts, which is worth more than forty suggestions. Watch for the client who drops a skill after one bad try; three uses, then the verdict.', '[{"id": "f0", "type": "textarea", "label": "The skill I am trialing this week, and how I will do it:"}, {"id": "f1", "type": "textarea", "label": "Use one: when, before and after out of 10, and what fit or did not:"}, {"id": "f2", "type": "textarea", "label": "Use two: when, before and after out of 10:"}, {"id": "f3", "type": "textarea", "label": "Use three: when, before and after out of 10:"}, {"id": "f4", "type": "textarea", "label": "Where this skill works for me and where it does not:"}, {"id": "f5", "type": "textarea", "label": "My verdict: keep, adapt or drop, and next week''s skill:"}]'::jsonb, array['coping skills', 'monitoring', 'skills']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('needing-a-skill-means-i-cannot-cope-on-my-own-belief-sheet', 'Needing a Skill Means I Cannot Cope on My Own Belief Sheet', 'cbt'::resource_kind, 'A belief sheet for the client who sees reaching for a coping skill as proof that they cannot handle life unaided.', 'Use it to examine the belief against what the client thinks of other people who use tools, and to reframe skills as equipment.', array['Adults', 'Teens']::text[], '15 minutes', 'Some clients resist skills not because they fail but because needing one feels like failing. The sheet asks for the belief, how much they hold it, what they think of a friend who takes a walk to cool down or a colleague who writes a list to think, the tools they use without shame in other areas (a map, a recipe, a calendar), what coping on their own has actually looked like this month, and a revised belief about equipment. Watch for the client who agrees in session and still refuses the skill at home; ask what the belief says in that moment.', '[{"id": "f0", "type": "textarea", "label": "The belief, in my words, and how much I hold it:"}, {"id": "f1", "type": "textarea", "label": "What I think of a friend who uses a skill to cool down or think:"}, {"id": "f2", "type": "textarea", "label": "Tools I use without shame elsewhere in life:"}, {"id": "f3", "type": "textarea", "label": "What coping on my own, with no skill, actually looked like this month:"}, {"id": "f4", "type": "textarea", "label": "A revised belief about skills as equipment:"}, {"id": "f5", "type": "textarea", "label": "How much I hold the old belief now:"}]'::jsonb, array['coping skills', 'core beliefs', 'self-criticism']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('coping-skill-as-a-flashlight-not-the-sun-page', 'Coping Skill as a Flashlight Not the Sun Page', 'act'::resource_kind, 'An ACT page that frames a coping skill as a flashlight: it lights the next few steps in the dark without pretending to be daylight.', 'Use it to reset a client''s expectation that a skill should fix the feeling, so they stop throwing away flashlights for not being the sun.', array['Adults', 'Teens']::text[], '10 minutes', 'A client who expects a skill to end the feeling discards every skill that does not. The page offers the flashlight: it does not make the night day, it shows the next few steps. The client lists skills they have abandoned for not being the sun, what each one did light (the next hour, the walk to the kitchen), what they wanted it to do instead, and what carrying a flashlight on purpose would look like this week. The frame is modest by design. Watch for the client who hears it as settling for less; ask how far a flashlight has got them before.', '[{"id": "f0", "type": "textarea", "label": "Skills I have abandoned because they did not end the feeling:"}, {"id": "f1", "type": "textarea", "label": "What each one did light, however little:"}, {"id": "f2", "type": "textarea", "label": "What I wanted it to do instead:"}, {"id": "f3", "type": "textarea", "label": "What walking the next few steps by flashlight would look like this week:"}, {"id": "f4", "type": "textarea", "label": "The flashlight I will carry on purpose, and when I will switch it on:"}, {"id": "f5", "type": "textarea", "label": "What it lit, and how far I got:"}]'::jsonb, array['coping skills', 'metaphor', 'workability']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('improve-the-moment-with-encouragement-in-the-mirror-card', 'IMPROVE the Moment With Encouragement in the Mirror Card', 'dbt'::resource_kind, 'A DBT IMPROVE card for the encouragement step, said to the client''s own face in the bathroom mirror before a hard hour.', 'Use it to give a client a short, specific coaching line they deliver to themselves out loud, as they would to a friend.', array['Adults', 'Teens']::text[], 'One minute before a hard hour', 'Encouragement in IMPROVE is the one step most clients skip because it feels silly, and the mirror makes it sillier and more effective. The card asks for the hard hour ahead, the line a good coach would say to the client before it (specific, true, forward-looking: you have done the hard first sentence before, do it again), the client''s own version, and the practice: said aloud to their face, once, with eye contact. Afterward they note what the hour was like and whether the line came back during it. Watch for lines that are demands (just get through it); the coach is kind.', '[{"id": "f0", "type": "textarea", "label": "The hard hour ahead:"}, {"id": "f1", "type": "textarea", "label": "What a good coach who knew me would say before it:"}, {"id": "f2", "type": "textarea", "label": "My own version of the line, in my words:"}, {"id": "f3", "type": "textarea", "label": "What it was like to say it aloud to my face:"}, {"id": "f4", "type": "textarea", "label": "Whether the line came back to me during the hour:"}, {"id": "f5", "type": "textarea", "label": "The line I will keep for next time:"}]'::jsonb, array['coping skills', 'IMPROVE', 'self-talk']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('coping-skill-relay-pass-the-card-and-do-it-game', 'Coping Skill Relay Pass the Card and Do It Game', 'game'::resource_kind, 'A relay game in which teams race to pass a stack of skill cards down the line, each player demonstrating the skill before passing it on.', 'Use it to get a group doing coping skills with their bodies, fast and together, so the skills are rehearsed rather than recited.', array['Groups', 'Teens']::text[], '20 minutes', 'Rules: two teams in lines, each with a stack of cards naming a quick skill (five slow breaths, name five blue things, press feet into the floor, shake out the hands, half smile). The first player draws a card, does the skill for real, and passes the card down; the next player does the same with the next card. A judge can send a card back if the skill was rushed. First team to pass every card wins. Second round: each player does the skill and names when they would use it. Debrief: which skills felt natural, which felt odd in public, and which one each member would reach for.', '[{"id": "f0", "type": "textarea", "label": "The cards I drew, and how I did each skill:"}, {"id": "f1", "type": "textarea", "label": "The skill that felt most natural in my body:"}, {"id": "f2", "type": "textarea", "label": "The skill that felt oddest to do in front of people:"}, {"id": "f3", "type": "textarea", "label": "In round two, the moment I named for one skill:"}, {"id": "f4", "type": "textarea", "label": "A skill someone else did that I want to try:"}, {"id": "f5", "type": "textarea", "label": "The one skill I would actually reach for this week:"}]'::jsonb, array['coping skills', 'game', 'skills']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('holding-the-neighbors-cat-step-plan-sheet', 'Holding the Neighbor''s Cat Step Plan Sheet', 'worksheet'::resource_kind, 'A step plan for the client whose fear of cats keeps them out of friends'' homes, built from looking through a window to holding one.', 'Use it to lay out small, repeatable steps toward a cat, each practiced until it is boring, with a friend and their cat enlisted.', array['Adults', 'Teens']::text[], 'Several short practices across a month', 'A fear of cats is socially expensive: it cancels dinners and makes the client the guest who flinches. The sheet lists steps from easy to hard (photos, a video, a cat across a room behind a door, a cat in the room with the client seated, a cat on the sofa beside them, a hand near, a hand on), with a predicted fear and an actual fear for each and a rule to repeat a step until it drops to a 3 before moving on. A friend with a calm cat is the practice partner. Watch for the client who jumps three steps on a brave day and then avoids for a month; the rule is the pace.', '[{"id": "f0", "type": "textarea", "label": "The steps from easiest to hardest, in my own words:"}, {"id": "f1", "type": "textarea", "label": "My predicted fear for each step, out of 10:"}, {"id": "f2", "type": "textarea", "label": "The friend and the cat I will practice with, and what I have asked of them:"}, {"id": "f3", "type": "textarea", "label": "Each step''s actual fear and how many repeats it took to drop to a 3:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the cat that I had not expected:"}, {"id": "f5", "type": "textarea", "label": "The step I am on today, and the next one:"}]'::jsonb, array['phobias', 'hierarchy', 'avoidance']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('the-snake-behind-the-glass-will-get-out-prediction-sheet', 'The Snake Behind the Glass Will Get Out Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet for the client who will not enter a pet store or a reptile house because the glass might fail.', 'Use it to write the prediction, estimate the odds, gather what is actually known about the enclosure, and test it with one visit.', array['Adults', 'Teens']::text[], '20 minutes, then one visit', 'The prediction is specific and the client has never tested it: the snake will get out and come for me. The sheet asks for it in detail, the odds the client gives it in the doorway, what they know about how the enclosures are built and what has happened on every past visit by anyone they know, a planned visit of a set length at a set distance from the glass, and the outcome. Keep the test modest and timed. Watch for the client who stands by the exit the whole visit and calls it done; the distance from the glass is part of the plan.', '[{"id": "f0", "type": "textarea", "label": "The prediction, in detail, including what the snake would do:"}, {"id": "f1", "type": "textarea", "label": "The odds I give it standing in the doorway, out of 100:"}, {"id": "f2", "type": "textarea", "label": "What I actually know about how the glass and the enclosure are built:"}, {"id": "f3", "type": "textarea", "label": "My planned visit: how long, how close, with whom:"}, {"id": "f4", "type": "textarea", "label": "What happened, minute by minute:"}, {"id": "f5", "type": "textarea", "label": "The odds I give it now, and the next visit:"}]'::jsonb, array['phobias', 'predictions', 'behavioral experiment']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('willing-to-grip-the-rail-on-the-ferris-wheel-page', 'Willing to Grip the Rail on the Ferris Wheel Page', 'act'::resource_kind, 'An ACT willingness page for the client who wants to ride the fair''s Ferris wheel with their kids and has refused for years.', 'Use it to choose the ride for its value, make room for the fear, and let the white knuckles come along.', array['Adults', 'Teens']::text[], '15 minutes, then one ride', 'The Ferris wheel is slow, high and impossible to leave once it starts, and it is also where the client''s kids want them. The page asks what the ride is for (who they would be sitting beside, what the kids would see in their face), what the fear says will happen at the top, what avoiding has cost at every fair so far, and what it would mean to grip the rail with both hands, feel the fear fully, and ride anyway. The gripping is allowed; the ride is the point. Watch for the client who plans to ride with their eyes closed the whole way; one look at the top is the ask.', '[{"id": "f0", "type": "textarea", "label": "Who I would be sitting beside, and what I want them to see in my face:"}, {"id": "f1", "type": "textarea", "label": "What the fear says will happen at the top:"}, {"id": "f2", "type": "textarea", "label": "What refusing has cost me at every fair so far:"}, {"id": "f3", "type": "textarea", "label": "What gripping the rail and riding anyway would mean about who I am:"}, {"id": "f4", "type": "textarea", "label": "The one thing I will look at from the top:"}, {"id": "f5", "type": "textarea", "label": "How the ride went, and what my hands did on the way down:"}]'::jsonb, array['phobias', 'willingness', 'values']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('paced-breathing-before-opening-the-basement-door-card', 'Paced Breathing Before Opening the Basement Door Card', 'dbt'::resource_kind, 'A DBT paced breathing card for the client who cannot go down to the basement alone and needs to do laundry there.', 'Use it to put a minute of slow breath between the hand on the door and the first step down, every time, until the stairs are ordinary.', array['Adults', 'Teens']::text[], 'One minute, before each trip', 'The basement door is where the client''s body says no, and bringing someone along every time is not sustainable. The card sets a ritual: hand on the knob, one minute of breath (in for four, out for six), eyes open, then the door and the first three steps with the light on, pausing on the third to breathe again if needed. Each trip is logged with the fear at the door and at the bottom. Watch for the client who breathes at the door and then runs down and up; the steps are slow, and the laundry is folded down there.', '[{"id": "f0", "type": "textarea", "label": "Fear at the door before the breath, out of 10:"}, {"id": "f1", "type": "textarea", "label": "My rhythm for the minute, and what my eyes were on:"}, {"id": "f2", "type": "textarea", "label": "Fear on the third step, and what I did there:"}, {"id": "f3", "type": "textarea", "label": "Fear at the bottom, and how long I stayed:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the basement that I had not before:"}, {"id": "f5", "type": "textarea", "label": "How many trips this week, and how the numbers moved:"}]'::jsonb, array['phobias', 'breathing', 'distress tolerance']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('brave-knight-meets-the-hair-clippers-play', 'Brave Knight Meets the Hair Clippers Play', 'kids'::resource_kind, 'A puppet play in which a child''s brave knight toy approaches the buzzing hair clippers in steps, with the parent working the clippers.', 'Use it to prepare a child who screams at the sound of clippers for a haircut, one buzz at a time, with the child in charge of the pace.', array['Children']::text[], '10 minutes a day for a week', 'The sound of clippers undoes a child before the barber has started. The play puts a brave knight (any figure) in charge: day one the knight looks at the clippers switched off; day two hears them buzz across the room for one second; day three the buzz comes closer; by the end of the week the knight is touched by the back of the running clippers and then the child''s hand is. The parent runs the clippers and the child says go and stop, and stop is always honored. Watch for the parent who pushes a step on a good day; the child sets the pace, and the knight gets a cheer at every step.', '[{"id": "f0", "type": "textarea", "label": "My knight''s name, and what makes them brave:"}, {"id": "f1", "type": "textarea", "label": "How far away the clippers were when the knight first heard the buzz:"}, {"id": "f2", "type": "textarea", "label": "What the knight did when the buzz came closer:"}, {"id": "f3", "type": "textarea", "label": "When I said stop, and what my grown-up did:"}, {"id": "f4", "type": "textarea", "label": "The day the knight let the clippers touch them, and what that was like:"}, {"id": "f5", "type": "textarea", "label": "What I will tell my knight on haircut day:"}]'::jsonb, array['phobias', 'children', 'play']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('comfortable-clothes-for-the-long-day-permission-sheet', 'Comfortable Clothes for the Long Day Permission Sheet', 'worksheet'::resource_kind, 'A permission sheet for the client who dresses to hide or to impress on a long day and spends it adjusting, tugging and uncomfortable.', 'Use it to choose the outfit for the day''s hours and the body''s comfort, and to notice what the discomfort has been protecting.', array['Adults', 'Teens']::text[], '15 minutes the night before', 'A long day in clothes chosen for how they look from outside is a day spent half inside the clothes. The sheet asks what the day holds (sitting, standing, eating, a drive), what the client usually wears to it and why, what the clothes do to them by hour three, what they would wear if comfort chose, and what the mind says would happen if they did. Then a permission line in their own words. No rules about bodies appear anywhere on it. Watch for the client who chooses comfort and spends the day apologizing for it; the permission is the practice.', '[{"id": "f0", "type": "textarea", "label": "What the day holds, hour by hour:"}, {"id": "f1", "type": "textarea", "label": "What I usually wear to a day like this, and why:"}, {"id": "f2", "type": "textarea", "label": "What those clothes do to me by hour three:"}, {"id": "f3", "type": "textarea", "label": "What I would wear if comfort chose:"}, {"id": "f4", "type": "textarea", "label": "What my mind says would happen if I wore that:"}, {"id": "f5", "type": "textarea", "label": "My permission line, in my own words, and how the day went in it:"}]'::jsonb, array['body image', 'self-care', 'permission']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('the-camera-angle-proves-it-thought-record', 'The Camera Angle Proves It Thought Record', 'cbt'::resource_kind, 'A thought record for the client who sees one unflattering photo and takes it as the final truth about how they look.', 'Use it to test what one angle can prove, against other photos, other people''s reactions and the client''s own view of photos of others.', array['Adults', 'Teens']::text[], '20 minutes', 'One photo from below, in bad light, and the client has their verdict. The record takes the photo, the hot thought (this is what I really look like, everyone sees this), the feeling, the evidence for the thought, and the evidence against (other photos the same day, what the person who took it said, what the client thinks when a friend hates a photo of themselves), and a balanced thought about what one angle can and cannot prove. Keep the sheet away from any talk of changing the body. Watch for the client who wants to review all their photos to settle it; one photo, one record.', '[{"id": "f0", "type": "textarea", "label": "The photo, and the hot thought it produced:"}, {"id": "f1", "type": "textarea", "label": "How strong the feeling was, out of 10, and how long it lasted:"}, {"id": "f2", "type": "textarea", "label": "Evidence that one photo is the truth about how I look:"}, {"id": "f3", "type": "textarea", "label": "Evidence against it (other photos, what the photographer said, how I see friends'' bad photos):"}, {"id": "f4", "type": "textarea", "label": "What one angle can prove, and what it cannot:"}, {"id": "f5", "type": "textarea", "label": "A balanced thought, and what I will do with the photo:"}]'::jsonb, array['body image', 'thought record', 'photos']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('body-as-the-kitchen-not-the-showroom-page', 'Body as the Kitchen Not the Showroom Page', 'act'::resource_kind, 'An ACT page that recasts the body as a working kitchen where life happens, rather than a showroom arranged to be looked at.', 'Use it to move a client''s attention from how the body appears to what it is doing and who it is feeding.', array['Adults', 'Teens']::text[], '10 minutes', 'A showroom exists to be seen; a kitchen exists to be used, and nobody judges a kitchen by whether the counters are camera-ready at dinnertime. The page asks the client to list what their body did today as a kitchen (carried, cooked, hugged, walked, laughed), what the showroom voice said about it, what they value doing with and in this body, and one thing tomorrow they will do in it as a kitchen, on purpose, with the showroom lights off. Nothing about shape or size appears. Watch for the client who turns the kitchen into a new standard (it must be a good kitchen); it is just where life happens.', '[{"id": "f0", "type": "textarea", "label": "What my body did today, as a kitchen:"}, {"id": "f1", "type": "textarea", "label": "What the showroom voice said about it:"}, {"id": "f2", "type": "textarea", "label": "What I value doing with and in this body:"}, {"id": "f3", "type": "textarea", "label": "One thing tomorrow I will do in it as a kitchen, on purpose:"}, {"id": "f4", "type": "textarea", "label": "What I noticed when the showroom lights were off for an hour:"}, {"id": "f5", "type": "textarea", "label": "Which rooms of my life are still showrooms, and one I could turn back into a kitchen:"}]'::jsonb, array['body image', 'values', 'metaphor']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-hiding-under-the-oversized-hoodie-card', 'Opposite Action to Hiding Under the Oversized Hoodie Card', 'dbt'::resource_kind, 'A DBT opposite action card for the client who wears the same shapeless hoodie to every social event to disappear inside it.', 'Use it to test whether the hiding fits the facts and to act opposite once, in a chosen outfit, with the shoulders back.', array['Adults', 'Teens']::text[], 'One event', 'The hoodie is a hiding place, and hiding feeds the shame that sent the client into it. The card checks whether the shame fits the facts (what would happen without the hoodie, honestly), and if not, the client acts opposite all the way: a chosen outfit they feel like themselves in, shoulders back, eye contact, staying the planned time. Afterward, shame before and after, what people actually did, and what the hoodie had been predicting. No talk of bodies appears on the card. Watch for the client who wears the new outfit under a coat all evening; the coat comes off.', '[{"id": "f0", "type": "textarea", "label": "What the hoodie does for me at an event, honestly:"}, {"id": "f1", "type": "textarea", "label": "Does the shame fit the facts? What would actually happen without it?"}, {"id": "f2", "type": "textarea", "label": "The outfit I chose, and why I feel like myself in it:"}, {"id": "f3", "type": "textarea", "label": "What acting opposite all the way looked like (shoulders, eyes, staying):"}, {"id": "f4", "type": "textarea", "label": "Shame before and after, out of 10, and what people actually did:"}, {"id": "f5", "type": "textarea", "label": "What the hoodie had been predicting, and what happened instead:"}]'::jsonb, array['body image', 'opposite action', 'shame']::text[], '2026-11-25T15:00:00+00:00'::timestamptz),
  ('no-body-talk-at-the-holiday-table-pact-for-partners', 'No Body Talk at the Holiday Table Pact for Partners', 'couples'::resource_kind, 'A couples pact for keeping comments about anyone''s body, their own included, out of the holiday meal, with a signal for relatives.', 'Use it to put both partners on the same side of the table when the appearance talk begins.', array['Couples']::text[], '15 minutes before the gathering', 'Holiday tables run on comments about how everyone looks, and one partner may not hear how much it costs the other. The pact asks each partner what body talk at the table does to them, what they themselves tend to say (about their own body too), a shared rule for the two of them (no comments on anyone''s appearance, including compliments that are really measurements), a signal for when a relative starts, and who changes the subject and how. Both partners sign up to their own part. Watch for the partner who thinks their own self-criticism out loud is harmless; it is on the list.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what body talk at the table does to me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what body talk at the table does to me:"}, {"id": "f2", "type": "textarea", "label": "What each of us tends to say about bodies, our own included, that we will stop:"}, {"id": "f3", "type": "textarea", "label": "Our rule for the two of us at the table:"}, {"id": "f4", "type": "textarea", "label": "Our signal when a relative starts, and who changes the subject with what:"}, {"id": "f5", "type": "textarea", "label": "How we will check in with each other on the drive home:"}]'::jsonb, array['body image', 'couples', 'holidays']::text[], '2026-11-25T15:00:00+00:00'::timestamptz)
